function updateSupportBadge(){
 const owner=String(state.data?.profile?.freeman_id||'');
 if(!owner||state.extra.activityNoticeOwner!==owner)return;
 const replies=(state.extra.activityNotices||[]).filter(isSupportReply);
 const key='freeman-support-read:'+owner;
 let read=[];
 try{const saved=JSON.parse(localStorage.getItem(key)||'[]');if(Array.isArray(saved))read=saved}catch{}
 const opened=replies.filter(isSupportReplyInOpenChat).map(n=>n.event_id);
 if(opened.length){read=[...new Set([...opened,...read])].slice(0,500);try{localStorage.setItem(key,JSON.stringify(read))}catch{}}
 const count=replies.filter(n=>!read.includes(n.event_id)&&!noticeIsRead(n)).length;
 for(const button of document.querySelectorAll('.mobile-nav [data-view="support"]')){
  let badge=button.querySelector('.fo-support-unread');
  if(!count){badge?.remove();button.removeAttribute('aria-label');continue}
  if(!badge){badge=document.createElement('span');badge.className='fo-support-unread';badge.setAttribute('aria-hidden','true');button.append(badge)}
  badge.textContent=count>99?'99+':count;
  badge.dataset.digits=badge.textContent.length;
  button.setAttribute('aria-label','Поддержка, непрочитанных ответов: '+count);
 }
}
/* In-page alerts observe committed records. They never enqueue bot deliveries. */
const AccountEventAlerts=(()=>{
 const memory=new Map();
 const key=owner=>'freeman-events-seen:'+owner;
 function current(){return String(state.data?.profile?.freeman_id||'')}
 function saved(owner){let stored=null;try{const value=JSON.parse(localStorage.getItem(key(owner))||'null');if(Array.isArray(value))stored=value.filter(x=>typeof x==='string')}catch{}const cached=memory.get(owner);return stored===null&&!cached?null:[...new Set([...(stored||[]),...(cached||[])])]}

 function remember(owner,ids){const value=[...new Set(ids)].slice(0,500);memory.set(owner,value);try{localStorage.setItem(key(owner),JSON.stringify(value))}catch{}}
 function dismiss(){FreemanComponents.dismissNoticeBanner(document.querySelector('.account-event-toast'))}
 function show(owner,items){
  if(owner!==current()||document.hidden)return;
  const before=saved(owner),ids=items.map(n=>n.event_id);
  if(before===null){remember(owner,ids);return}
  const fresh=items.filter(n=>!before.includes(n.event_id)&&!noticeIsRead(n));
  const pending=fresh.filter(n=>!isSupportReplyInOpenChat(n));
  if(!pending.length||document.querySelector('.digest-toast')){
   if(fresh.length!==pending.length)remember(owner,[...fresh.filter(isSupportReplyInOpenChat).map(n=>n.event_id),...before]);
   return;
  }
  remember(owner,[...ids,...before]);
  const n=pending.find(isSupportReply)||pending[0],reply=isSupportReply(n),[iconName,tone]=noticePresentation(n);
  FreemanComponents.showNoticeBanner({
   className:'account-event-toast'+(reply?' fo-support-notice-banner':''),iconName,tone,
   avatarUser:reply?supportNoticeAvatar:null,
   label:reply?'':'Freeman ONE'+(pending.length>1?' · ещё '+(pending.length-1):''),
   title:reply?supportNoticeAvatar.name:n.title,text:reply?n.message_preview:noticePlain(n.text),duration:8000,
   openAttributes:`data-account-event="${esc(n.event_id)}"`,dismissAttributes:'data-account-event-dismiss'
  });
  if(NoticeCenter.soundOn())playSupportSentSound();
 }
 async function receive(owner,items){try{if(navigator.locks)await navigator.locks.request(key(owner),()=>show(owner,items));else show(owner,items)}catch{}}
 document.addEventListener('click',e=>{
  const b=e.target.closest('[data-account-event],[data-account-event-dismiss]');if(!b)return;
  dismiss();
  if(!b.dataset.accountEvent||!state.data)return;
  const n=state.extra.activityNotices?.find(x=>x.event_id===b.dataset.accountEvent);
  if(!n)return;
  if(isSupportReply(n)){void openSupportNotice(n.ticket_id);return}
  state.modal=notificationDetail(n);render();
 });
 function dismissInOpenChat(){
  const button=document.querySelector('.fo-support-notice-banner [data-account-event]');
  if(button&&state.extra.activityNotices?.some(n=>n.event_id===button.dataset.accountEvent&&isSupportReplyInOpenChat(n)))dismiss();
 }
 function refresh(){if(state.data&&!isPreview()&&!document.hidden)void NoticeCenter.load().catch(()=>{})}
 setInterval(refresh,20000);window.addEventListener('focus',refresh);document.addEventListener('visibilitychange',refresh);
 return {receive,dismissInOpenChat};
})();

function commonTopbar(){const unread=accountNotifications(state.data).filter(n=>!noticeIsRead(n)).length;return `<header class="profile-topbar fo-shell-header fo-scope" data-fo-surface><div class="profile-brand"><img src="/assets/freeman-mark-20261029.png" alt=""><strong class="dia-brand-text">Freeman ONE</strong></div><div class="profile-header-actions fo-header-actions"><button class="notification-bell fo-button fo-icon-button" data-notifications aria-label="Уведомления${unread?`: непрочитанных ${unread}`:''}">${unread?'<span class="fo-notice-count" aria-hidden="true">'+(unread>99?'99+':unread)+'</span>':''}${svg('bell')}</button><button class="fo-button fo-icon-button" data-profile-settings aria-label="Настройки">${svg('settings')}</button>${themeSwitch()}</div></header>`}
function noticePresentation(n){
  if(n.publication_id)return ['file-text','info'];
  if(n.digest_id&&n.kind!=='withdrawal')return ['chart','info'];
  const kind=n.kind||(/подписк|срок|proxy/i.test(n.title)?'expiry':/баланс|начислен|выплат/i.test(n.title)?'money':/обращени|поддержк/i.test(n.title)?'support':'message');
  return ({money:['wallet','success'],withdrawal:['wallet','success'],referral:['users','info'],payment:['credit-card','success'],expiry:['clock','warning'],warning:['alert','danger'],support:['headset','info']})[kind]||['bell',n.important?'warning':'info'];
}
function noticeDate(n){const date=new Date(n.occurred_at||n.created_at||'');return Number.isFinite(date.getTime())?`<time datetime="${esc(date.toISOString())}">${esc(new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}).format(date))}</time>`:''}
function notificationRows(notices){
 const all=accountNotifications(state.data);let group='';
 return `<div class="animated-notice-list fo-notice-list">${notices.map(n=>{const[icon,tone]=noticePresentation(n),reply=isSupportReply(n),read=noticeIsRead(n),d=new Date(n.occurred_at||n.created_at||''),valid=Number.isFinite(d.getTime()),day=valid?d.toLocaleDateString('ru-RU',{timeZone:'Europe/Moscow',day:'numeric',month:'long'}):'События',title=day!==group?`<h3 class="fo-notice-group">${esc(day)}</h3>`:'';group=day;return title+FreemanComponents.noticeRow({title:reply?supportNoticeAvatar.name:n.title,text:reply?n.message_preview:noticePlain(n.text),avatarUser:reply?supportNoticeAvatar:null,iconName:icon,tone,read,date:noticeDate(n),attributes:`data-notice-open="${all.findIndex(item=>noticeId(item)===noticeId(n))}" data-notice-key="${esc(noticeToken(n))}"`,readAttributes:read?'':`data-notice-read="${esc(noticeId(n))}"`})}).join('')}</div>`;
}
function importantNotifications(d){const notices=accountNotifications(d).filter(n=>!noticeIsRead(n));return notices.length?`<section class="profile-notices fo-notice-preview" aria-label="Уведомления"><header><div class="fo-notice-preview-title">${FreemanComponents.noticeIcon('bell')}<h2>Уведомления</h2><span class="fo-count">${notices.length}</span></div><button type="button" class="fo-button fo-button--plain fo-button--compact" data-notifications>Все ${actionIcon('chevron-right')}</button></header>${notificationRows(notices.slice(0,3))}<footer><button type="button" class="fo-button fo-button--plain fo-button--compact" data-notice-all>${FreemanComponents.icon('check')}Прочитать всё</button></footer></section>`:''}
function notificationTarget(n){
  if(n.kind==='message')return null;
  if(n.kind==='support'&&Number.isSafeInteger(n.ticket_id)&&n.ticket_id>0)return {kind:'support',value:n.ticket_id};
  const views=['keys','plans','support','profile','instructions','faq','proxy','balance','referrals','admin-reports','admin-payments','clients','posts'];
  if(n.digest_id)return {kind:'digest',value:String(n.digest_id)};
  if(/^[1-9]\d*$/.test(String(n.sid))&&Number.isSafeInteger(Number(n.sid)))return {kind:'renew',value:Number(n.sid)};
  if(/^[1-9]\d*$/.test(String(n.publication_id))&&Number.isSafeInteger(Number(n.publication_id)))return {kind:'post',value:String(n.publication_id)};
  const target=String(n.target||'').trim();if(views.includes(target))return {kind:'view',value:target};
  try{const url=new URL(target,location.origin);if(!target||url.username||url.password||!['https:','http:'].includes(url.protocol))return null;
    if(url.origin===location.origin){
      const post=url.searchParams.get('post');if(/^[1-9]\d*$/.test(post||'')&&Number.isSafeInteger(Number(post)))return {kind:'post',value:post};
      const section=url.searchParams.get('section');if(views.includes(section))return {kind:'view',value:section};
      const payout=url.searchParams.get('referral_payout');if(state.data?.profile?.is_admin&&/^[1-9]\d*$/.test(payout||''))return {kind:'digest',value:'payout-'+payout};
      const day=url.searchParams.get('daily_report');if(state.data?.profile?.is_admin&&/^\d{4}-\d{2}-\d{2}$/.test(day||''))return {kind:'digest',value:day};
      if(url.pathname==='/'||url.pathname===location.pathname&&!url.search)return null;
    }
    return url.protocol==='https:'?{kind:'link',value:url.href}:null;
  }catch{return null}
}
function notificationsModal(d){const all=accountNotifications(d),archive=state.extra.noticeTab==='archive',notices=all.filter(n=>noticeIsRead(n)===archive),unread=all.filter(n=>!noticeIsRead(n)).length;return `<div class="fo-overlay fo-scope fo-notice-overlay" data-fo-overlay><section class="fo-dialog notifications-panel fo-notification-center" data-fo-panel role="dialog" aria-modal="true" aria-labelledby="notifications-title"><header class="fo-dialog-header">${FreemanComponents.noticeIcon('bell')}<div class="fo-notice-heading"><h2 id="notifications-title">Уведомления</h2><p>${unread?'Непрочитанных: '+unread:'Вы всё прочитали'}</p></div><button type="button" class="fo-button fo-icon-button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button></header><nav class="fo-tabs fo-tabs--compact fo-notice-tabs" aria-label="Уведомления"><button type="button" data-notice-tab="new" aria-pressed="${!archive}">Новые${unread?' · '+unread:''}</button><button type="button" data-notice-tab="archive" aria-pressed="${archive}">Архив</button></nav><div class="fo-notice-toolbar"><span>${archive?'Сохранённые события':'Для вас'}</span><button class="fo-button fo-button--plain fo-button--compact" type="button" ${archive?'data-notice-clear':'data-notice-all'} ${!notices.length||NoticeCenter.busy?'disabled':''}>${FreemanComponents.icon(archive?'trash':'check')}${archive?'Очистить архив':'Прочитать всё'}</button></div><div class="fo-notice-scroll" data-notice-scroll="${archive?'archive':'new'}" tabindex="0" aria-label="Список уведомлений">${notices.length?notificationRows(notices):`<div class="fo-empty">${FreemanComponents.noticeIcon('bell')}<p>${archive?'Архив пуст':'Новых уведомлений нет'}</p></div>`}</div>${typeof PublicationAlerts!=='undefined'?PublicationAlerts.settings({open:!!document.querySelector('.notifications-panel .fo-notice-settings[open]')}):''}<p data-notice-error class="fo-feedback fo-feedback--error" role="alert" hidden></p></section></div>`}

function notificationDetail(n){
  const target=notificationTarget(n);let action='';
  if(target?.kind==='digest')action=`<button type="button" class="fo-button fo-button--primary" data-digest-open="${esc(target.value)}">${n.kind==='withdrawal'||target.value.startsWith('payout-')?'Открыть заявку':n.kind==='test'?'Понятно':'Открыть отчёт за день'}</button>`;
  if(target?.kind==='support')action=`<button type="button" class="fo-button" data-notice-support="${target.value}">Открыть обращение</button>`;
  if(target?.kind==='renew')action=`<a class="fo-button fo-button--success" href="/?renew=${target.value}">Продлить подписку</a>`;
  if(target?.kind==='post')action=`<button type="button" class="fo-button fo-button--primary" data-post-open="${target.value}">Открыть публикацию</button>`;
  if(target?.kind==='view')action=`<button type="button" class="fo-button" data-view="${target.value}">Перейти в раздел</button>`;
  if(target?.kind==='link')action=`<a class="fo-button" href="${esc(target.value)}" target="_blank" rel="noopener noreferrer">Подробнее</a>`;
  return `<div class="fo-overlay fo-scope fo-notice-overlay" data-fo-overlay><section class="fo-dialog notice-detail" data-tone="${noticePresentation(n)[1]}" data-fo-panel role="dialog" aria-modal="true" aria-labelledby="notice-detail-title"><header class="fo-dialog-header">${FreemanComponents.noticeIcon(...noticePresentation(n))}<h2 id="notice-detail-title">${esc(n.title)}</h2><button type="button" class="fo-button fo-icon-button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button></header><div class="notice-detail-body">${noticeDate(n)}<div class="notice-rich-text">${noticeMarkup(n.text)}</div></div><footer class="fo-dialog-actions notice-detail-actions">${!noticeIsRead(n)?`<button type="button" class="fo-button fo-button--compact notice-read-button" data-notice-read="${esc(noticeId(n))}">Прочитано</button>`:'<span class="notice-read-label">Прочитано</span>'}${action}</footer></section></div>`;
}

