function updateCheckoutSelection(){
  const tariff=state.data.tariffs.find(x=>x.id===state.selectedPlan);if(!tariff)return;
  document.querySelectorAll('[data-plan]').forEach(button=>{const active=+button.dataset.plan===tariff.id;button.classList.toggle('selected',active);button.setAttribute('aria-checked',String(active));button.tabIndex=active?0:-1});
  document.querySelectorAll('[data-payment-method]').forEach(button=>{const active=button.dataset.paymentMethod===state.paymentMethod;button.classList.toggle('selected',active);button.setAttribute('aria-pressed',String(active))});
  const amount=state.data.payments?.owner_free?0:purchaseAmount(tariff);
  const antigCard=document.querySelector('.fo-antig-card');if(antigCard)FreemanComponents.updateAntigOption(antigCard,{available:state.extra.antig?.enabled,selected:siteAntigSelected(),surcharge:state.extra.antig?.prices?.[tariff.id]||0,disabled:state.busy});
  const devices=document.querySelector('[data-selected-devices]'),method=document.querySelector('[data-selected-method]'),sum=document.querySelector('[data-selected-amount]'),checkout=document.querySelector('[data-checkout]');
  if(devices)devices.textContent=tariff.device_limit;if(method)method.textContent=state.paymentMethod==='balance'?'Баланс':'Карта или СБП';if(sum)sum.textContent=planRub(amount);if(checkout)checkout.textContent=state.data.payments?.owner_free?'Выпустить бесплатно':`Оплатить ${planRub(amount)}`;
}
function attachmentMarkup(item){return FreemanComponents.media(item)}
function supportDate(value){const stamp=new Date(value),now=new Date(),same=stamp.toDateString()===now.toDateString(),yesterday=new Date(now);yesterday.setDate(now.getDate()-1);const prefix=same?'Сегодня':stamp.toDateString()===yesterday.toDateString()?'Вчера':new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short'}).format(stamp);return `${prefix}, ${new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit'}).format(stamp)}`}
