 const status=({waiting_admin:admin?'Не решено':'Ждём ответа',waiting_client:admin?'Ждёт клиента':'Ждём вас',in_progress:'В работе',needs_info:'Нужны данные',closed:'Решено'})[item.status]||'Открыто';
 return FreemanComponents.conversation({name,identity:admin?[(item.important?'★ Важное':''),client.freeman_id||''].filter(Boolean).join(' · '):'#'+item.id,preview:item.last_message||item.subject,avatar:admin?client:{avatar:'/assets/freeman-mark-20261029.png'},when:supportDate(item.updated_at),datetime:item.updated_at,status,tone:({closed:'danger',waiting_admin:'warning',in_progress:'success',needs_info:'info',waiting_client:'neutral'})[item.status]||'neutral',unread:item.unread,attributes:`data-support-ticket="${Number(item.id)}" aria-pressed="${Number(state.supportTicket)===Number(item.id)}" aria-label="Открыть переписку: ${esc(name)}"`,className:'fo-conversation'});
