  return `<div class="modal-backdrop"><form class="form-modal payout-form" ${withdraw?'data-withdraw-form':'data-payout-form'}><button type="button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>${withdraw?'Вывод средств':state.extra.withdrawAfterDetails?'Шаг 1 · Данные для вывода':'Данные для вывода'}</h2><p>${withdraw?`Минимум ${planRub(x.withdraw_min)}. Доступно ${planRub(x.balance)}.`:'Укажите реквизиты получателя. Их можно изменить в любой момент.'}</p><label>Имя получателя<input name="owner_name" required minlength="3" maxlength="120" autocomplete="name" value="${esc(details.owner_name||'')}" placeholder="Имя и фамилия"></label><label>Банк<input name="bank" required minlength="2" maxlength="100" value="${esc(details.bank||'')}" placeholder="Название банка"></label><label>Способ перевода<select name="method" data-payout-method><option value="phone" ${method==='phone'?'selected':''}>По телефону · СБП</option><option value="card" ${method==='card'?'selected':''}>На банковскую карту</option></select></label><label><span data-payout-account-label>${method==='card'?'Номер карты':'Телефон, привязанный к банку'}</span><input name="account" required inputmode="tel" maxlength="32" autocomplete="off" value="${esc(details.account||'')}" placeholder="${method==='card'?'16–19 цифр':'+7 900 000-00-00'}"></label>${withdraw?`<label>Сумма, ₽<div class="amount-line"><input name="amount" required type="number" min="${x.withdraw_min/100}" max="${x.balance/100}" step="0.01" placeholder="От ${x.withdraw_min/100} ₽"><button type="button" data-all-amount="${x.balance/100}">Вся сумма</button></div></label>`:''}<p class="login-form-error" role="alert" hidden></p><button class="checkout-button" type="submit">${withdraw?'Отправить заявку':state.extra.withdrawAfterDetails?'Продолжить':'Сохранить данные'}</button></form></div>`;
