async function openPayoutForm(withdraw=false){
 try{
  if(!withdraw)state.extra.withdrawAfterDetails=false;
  if(withdraw&&await recoverWithdrawal()){render();return}
  const x=state.extra.balance;if(withdraw&&!x.withdraw_enabled){state.modal='<div class="modal-backdrop"><section class="form-modal"><button data-close-modal aria-label="Закрыть">'+actionIcon('close')+'</button><h2>Вывод временно недоступен</h2><p>Обратитесь в поддержку или попробуйте позже.</p><button class="checkout-button" data-view="support" data-close-modal>Поддержка</button></section></div>';render();return}
  let details=state.extra.previewPayout||{};
  if(!isPreview()){const response=await fetch('/api/web/payout-details');const result=await response.json();if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:'Не удалось загрузить данные');details=result.details||{}}
  if(withdraw&&(!details.account||!details.bank||!details.owner_name)){state.extra.withdrawAfterDetails=true;state.modal=payoutForm({},false).replace('Укажите реквизиты получателя. Их можно изменить в любой момент.','Перед выводом добавьте банк, имя получателя и карту или телефон для СБП.');render();return}if(withdraw&&x.balance<x.withdraw_min){state.modal=`<div class="modal-backdrop"><section class="form-modal"><button data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>Вывод от ${planRub(x.withdraw_min)}</h2><p>На балансе ${planRub(x.balance)}. До минимальной суммы не хватает ${planRub(x.withdraw_min-x.balance)}.</p><button class="checkout-button" data-close-modal>Понятно</button></section></div>`;render();return}state.extra.withdrawAfterDetails=false;state.modal=payoutForm(details,withdraw);render();
 }catch(error){say(error.message)}
}
