function balancePage(){
 if(state.data?.profile?.is_admin)return adminSalesBalancePage();
 const x=state.extra.balance,header=`<header class="simple-header wallet-heading"><button class="fo-button fo-icon-button fo-button--compact" data-view="profile" aria-label="Назад в профиль">${actionIcon('back')}</button><h1>Баланс</h1></header>`;
 if(!x)return `<section class="wallet-page fo-scope">${header}<p role="status">Загружаем операции…</p></section>`;
 const operations=x.operations||x.transactions||[],filtered=state.balanceFilter==='all'?operations:operations.filter(o=>state.balanceFilter==='income'?o.amount>0:o.amount<0),statusLabels={manual_paid:'Оплата получена',manual_unpaid:'Не оплачено',manual_preparing:'Выдача готовится',manual_received_pending:'Оплата получена · выдача проверяется'};
 const rows=filtered.map(o=>`<div class="wallet-ledger-row"><span class="wallet-operation-icon" data-income="${o.amount>=0}" aria-hidden="true">${actionIcon(o.amount>=0?'plus-circle':'wallet')}</span><span class="wallet-operation-copy"><span>${esc(o.description||'Операция')}</span><small>${esc(date(o.created_at))}${o.status&&o.status!=='completed'?` · ${esc(statusLabels[o.status]||o.status)}`:''}</small></span><span class="wallet-operation-amount" data-income="${o.amount>=0}">${o.amount>=0?'+':''}${planRub(o.amount)}</span></div>`).join('');
 const payouts=customerPayoutHistory(x).replace('class="data-card"','class="fo-card wallet-withdrawals"');
 return `<section class="wallet-page fo-scope">${header}<section class="fo-card wallet-summary"><div class="wallet-available"><span class="wallet-summary-icon" aria-hidden="true">${actionIcon('wallet')}</span><div><small>Доступно на балансе</small><span>${planRub(x.balance)}</span></div></div><div class="wallet-actions"><button class="fo-button fo-button--success fo-button--glass fo-button--compact" data-topup>${actionIcon('plus-circle')}<span>Пополнить</span></button><button class="fo-button fo-button--compact" data-withdraw aria-disabled="${!x.withdraw_enabled}">${actionIcon('chevron-right')}<span>Вывести</span></button></div><small>Баланс можно использовать для покупки и продления подписок.</small></section>
 <nav class="wallet-services" aria-label="Управление балансом"><a class="fo-button fo-button--row wallet-service" href="/account">${actionIcon('card')}<span>Карты и автопродление</span>${actionIcon('chevron-right')}</a><button class="fo-button fo-button--row wallet-service" data-view="referrals">${actionIcon('users')}<span>Хочу заработать</span>${actionIcon('chevron-right')}</button></nav>
 <section class="fo-card wallet-requisites"><div class="wallet-section-heading"><div><h2>Данные для вывода</h2><small>Минимальная сумма — ${planRub(x.withdraw_min)}</small></div><button class="fo-button fo-button--compact" data-payout-edit>${x.payout_details?'Изменить':'Добавить'}</button></div>${x.payout_details?`<details class="wallet-details"><summary class="fo-disclosure">${esc(x.payout_details.bank||'Реквизиты получателя')}${actionIcon('chevron-down')}</summary><dl><div><dt>Получатель</dt><dd>${esc(x.payout_details.owner_name)}</dd></div><div><dt>Банк</dt><dd>${esc(x.payout_details.bank)}</dd></div><div><dt>${x.payout_details.method==='card'?'Карта':'Телефон · СБП'}</dt><dd>${esc(x.payout_details.account)}</dd></div></dl></details>`:'<p>Добавьте банк и реквизиты получателя, чтобы подать заявку на вывод.</p>'}<small>${!x.withdraw_enabled?'Вывод временно недоступен.':x.balance>=x.withdraw_min?'На балансе достаточно для заявки на вывод.':`До минимальной суммы — ${planRub(x.withdraw_min-x.balance)}.`}</small></section>${payouts}
 <section class="fo-card wallet-history"><div class="wallet-section-heading"><h2>История операций</h2><span class="wallet-record-count">${filtered.length}</span></div><div class="wallet-filters" role="group" aria-label="Фильтр операций">${[['all','Все'],['income','Поступления'],['expense','Расходы']].map(([id,text])=>`<button class="fo-button fo-button--compact" data-balance-filter="${id}" aria-pressed="${state.balanceFilter===id}">${text}</button>`).join('')}</div>${rows||'<p class="wallet-empty">В этой категории операций пока нет.</p>'}</section></section>`;
}
function referralPage(){if(state.data?.profile?.is_admin)return adminReferralPage();
 const x=state.extra.referrals,header=`<header class="simple-header"><button class="fo-button fo-icon-button fo-button--compact" data-view="profile" aria-label="Назад в профиль">${actionIcon('back')}</button><h1>Хочу заработать</h1></header>`;
 if(!x||x.error)return `<section class="earn-page fo-scope">${header}<p role="status">${x?.error?'Не удалось загрузить данные.':'Загружаем…'}</p>${x?.error?'<button class="fo-button" data-referral-retry>Повторить</button>':''}</section>`;
 const invited=x.invited||0,buyers=x.buyers||0,first=x.first_percent??15,repeat=x.repeat_percent??5,levels=x.personal?[]:x.levels||[],current=levels.find(t=>t.tier===x.tier),next=levels.find(t=>t.tier>(x.tier||1)),remaining=x.next_level_remaining??(next?Math.max(0,next.min_invited-invited):0),start=current?.min_invited||0,goal=next?.min_invited||invited,progress=next?Math.max(0,Math.min(100,(invited-start)/Math.max(1,goal-start)*100)):100;
 const filter=state.extra.referralHistoryFilter||'all',history=x.history||[],filtered=history.filter(i=>filter==='all'||(filter==='registered'?i.status==='waiting_for_purchase':!['waiting_for_purchase','registered'].includes(i.status))),visible=filtered.slice(0,state.referralHistoryVisible);
 const journeyGoal=levels.at(-1)?.min_invited||Math.max(1,invited),journeyProgress=Math.min(100,Math.max(0,invited/journeyGoal*100)),secondStop=Math.min(90,Math.max(10,(levels[1]?.min_invited||journeyGoal/2)/journeyGoal*100));
 const progressKey=[invited,x.tier,journeyGoal,journeyProgress].join(':');
 const maximumRate=Math.max(first,repeat,...levels.flatMap(t=>[Number(t.first_percent)||0,Number(t.repeat_percent)||0]));
 const rows=visible.map(i=>{const labels={reward_credited:'Деньги начислены',purchased:'Покупка',cancelled:'Начисление отменено',reward_ineligible:'Без начисления',waiting_for_purchase:'Регистрация',registered:'Регистрация'},date=Date.parse(i.occurred_at);return `<tr><td><time datetime="${esc(i.occurred_at||'')}">${Number.isFinite(date)?esc(new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short'}).format(date)): '—'}<small>${Number.isFinite(date)?esc(new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit'}).format(date)):''}</small></time></td><td><span class="earn-person-name">${esc(i.name||i.masked_user_label||'Клиент')}</span><small class="earn-person-id">${esc(i.freeman_id||'ID пока не выдан')}</small></td><td><span class="earn-event" data-reward="${i.status==='reward_credited'}">${esc(labels[i.status]||'Регистрация')}</span></td><td class="earn-purchase-amount">${Number.isInteger(i.payment_amount)?planRub(i.payment_amount):'—'}</td><td>${i.status==='reward_credited'&&i.reward_amount>0?`<span class="earn-reward">+${planRub(i.reward_amount)}</span>`:i.reward_status==='ineligible'?'0 ₽':i.reward_status==='reversed'?'<span class="earn-reversed">Отменён</span>':'—'}</td></tr>`}).join('');

 return `<section class="earn-page fo-scope">${header}${x.enabled===false?'<p class="fo-feedback">Начисление денег временно отключено.</p>':''}
 <div class="earn-promo-group" data-earn-promo>${ReferralAnimatedHero.render({rate:maximumRate})}<section class="fo-card earn-link earn-promo" aria-label="Ваша реферальная ссылка и баланс"><div class="earn-promo-tools"><button class="earn-promo-balance fo-button fo-button--compact" data-view="balance" aria-label="Открыть баланс"><span>${actionIcon('banknote')}<small>Ваш баланс</small></span><span>${planRub(x?.available_balance??state.data.balance)}</span>${actionIcon('chevron-right')}</button><div class="earn-referral-tools"><span class="earn-referral-label" id="earn-referral-label">Ваша ссылка</span><div class="ref-invite-link"><code aria-labelledby="earn-referral-label">${esc(x.link||'')}</code></div><div class="earn-share-actions"><button class="fo-button fo-button--primary-solid fo-button--compact" data-copy-ref="${esc(x.link||'')}">${actionIcon(state.referralCopied?'check':'copy')}<span>${state.referralCopied?'Скопировано':'Копировать'}</span></button><button class="fo-button fo-button--compact" aria-label="Поделиться ссылкой" data-share-ref="${esc(x.link||'')}">${actionIcon('share')}<span>Поделиться</span></button></div></div></div><span class="sr-only" data-ref-copy-status aria-live="polite"></span></section></div> ${!x.personal?`<section class="earn-quick-progress" role="button" tabindex="0" data-earn-journey aria-label="Перейти к вашему пути в программе. Уровень ${x.tier||1}" data-earn-progress-key="${esc(progressKey)}"><span class="earn-progress-symbol" aria-hidden="true">${actionIcon('chart')}</span><div><span>Ваш прогресс</span><small>${next?`Ещё ${remaining} приглашений до следующего шага`:'Все условия программы открыты'}</small></div><span class="earn-progress-count">${invited} / ${journeyGoal}</span><div class="earn-progress-track" role="progressbar" aria-label="Ваш путь в программе" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(journeyProgress)}" aria-valuetext="${invited} приглашений, уровень ${x.tier||1}" style="--earn-green-stop:${secondStop}%"><span style="width:${journeyProgress}%;background-size:${journeyProgress?10000/journeyProgress:100}% 100%"></span></div></section>`:''}
 <section class="fo-card earn-explainer"><section class="earn-how"><h2>Как это работает</h2><p>Три простых шага к первым деньгам</p><ol><li>Отправьте ссылку другу. После регистрации приглашение закрепляется за вами.</li><li>После успешной покупки начисляется ${first}%, за повторные покупки — ${repeat}%.</li><li>${x.withdraw_enabled===false?'Деньгами можно оплачивать подписку. Вывод временно отключён.':`Деньгами можно оплачивать подписку или оформить вывод от ${planRub(x.withdraw_min??100000)}.`}</li></ol><p>За регистрацию и пополнение баланса денег нет. При возврате платежа соответствующее начисление отменяется.${x.minimum_purchase?` Минимальная покупка: ${planRub(x.minimum_purchase)}.`:''}</p></section><details class="earn-details"><summary class="fo-disclosure">Условия программы ${actionIcon('chevron-down')}</summary><div class="ref-levels">${levels.map(t=>`<p>Уровень ${t.tier}: от ${t.min_invited} приглашений · ${t.first_percent}% за первую и ${t.repeat_percent}% за повторные покупки.</p>`).join('')||'<p>Для вас действуют персональные условия, указанные выше.</p>'}</div><p>Условия применяются к новым начислениям. Ранее начисленные деньги не пересчитываются.</p></details></section><section class="fo-card earn-program ref-terms-panel" id="earn-journey" tabindex="-1"><div class="earn-section-heading"><span class="earn-program-icon">${actionIcon('chart')}</span><div><small>${x.personal?'Ваше вознаграждение':'Ваш путь в программе'}</small><h2>${x.personal?'Ваши персональные условия':'Уровень '+(x.tier||1)}</h2></div><span class="fo-status" data-tone="success">${x.personal?'Персонально':invited+' приглашений'}</span></div><div class="ref-terms-rates earn-rates"><span><span>${first}%</span><small>Первая покупка</small></span><span><span>${repeat}%</span><small>Повторные покупки</small></span></div>${!x.personal?`<div class="earn-progress"><div class="earn-progress-heading"><span>${next?'Следующий шаг — уровень '+next.tier:'Все уровни открыты'}</span><span>${next?invited+' / '+goal:invited}</span></div><small>${next?`До уровня ${next.tier}: ${remaining} приглашений`:'Максимальный уровень достигнут'}</small><div class="earn-milestones">${levels.map(t=>`<div data-reached="${(x.tier||1)>=t.tier}" aria-current="${(x.tier||1)===t.tier?'step':'false'}"><span>${(x.tier||1)>t.tier?actionIcon('check'):t.tier}</span><div><span>Уровень ${t.tier}</span><small>От ${t.min_invited} приглашений</small><small>${t.first_percent}% / ${t.repeat_percent}%</small></div></div>`).join('')}</div></div>`:'<p>Персональные проценты действуют вместо общих уровней.</p>'}</section>
 <section class="ref-results earn-results" aria-label="Результаты приглашений"><div><i>${actionIcon('users')}</i><span>${invited}</span><small>Приглашено</small></div><div><i>${actionIcon('check')}</i><span>${buyers}</span><small>Купили</small></div><div><i>${actionIcon('wallet')}</i><span>${planRub(x.earned||0)}</span><small>Заработано</small></div></section><section class="fo-card ref-history earn-history"><div class="earn-history-heading"><span>${actionIcon('users')}</span><div><h2>История приглашений</h2><small>Регистрации, покупки и ваши деньги</small></div></div><div class="earn-tabs" role="group" aria-label="Фильтр приглашений">${[['all','Обзор'],['buyers','Купили'],['registered','Зарегистрировались']].map(([id,text])=>`<button class="fo-button fo-button--compact" data-ref-history-filter="${id}" aria-pressed="${filter===id}">${text}</button>`).join('')}</div>${rows?`<small class="earn-table-hint">Листайте таблицу вправо, чтобы увидеть покупку и деньги →</small><div class="earn-table-scroll" tabindex="0" role="region" aria-label="Таблица приглашений: прокрутите вправо для сумм"><table class="earn-table"><caption class="sr-only">История приглашений и денег</caption><thead><tr><th scope="col">Дата и время</th><th scope="col">Имя / Freeman ID</th><th scope="col">Событие</th><th scope="col">Покупка</th><th scope="col">Деньги</th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p class="earn-empty">Пока нет приглашений в этой категории.</p>'}<small>Покупка и начисленные деньги показаны одной строкой. Начисления сохраняются по условиям на дату покупки.</small>${filtered.length>state.referralHistoryVisible?'<button class="fo-button fo-button--compact" data-referral-more>Показать ещё</button>':''}${x.visits_tracked===false?'<small>Показываем регистрации и покупки. Открытия ссылки не отслеживаются.</small>':''}</section></section>`;
}

function openEarningsJourney(){const target=document.querySelector('.screen:not([hidden]) #earn-journey');if(!target)return;target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}
document.addEventListener('click',e=>{if(e.target.closest('[data-earn-journey]'))openEarningsJourney()});
document.addEventListener('keydown',e=>{if(e.target.matches('[data-earn-journey]')&&['Enter',' '].includes(e.key)){e.preventDefault();openEarningsJourney()}});
function mountEarningsProgress(target){
 const node=target.querySelector('[data-earn-progress-key]');if(!node)return;
 requestAnimationFrame(()=>{if(!node.isConnected||target.hidden||node.dataset.earnProgressKey===state.extra.earnProgressSeen)return;node.classList.add('earn-progress-fresh');state.extra.earnProgressSeen=node.dataset.earnProgressKey});
}

function telegramProxyLink(value){
  try {
    const url=new URL(value);
    return (url.protocol==='tg:'&&url.hostname==='proxy') ||
      (url.protocol==='https:'&&url.hostname==='t.me'&&url.pathname==='/proxy');
  } catch { return false; }
}
function proxyPurchaseModal(){const x=state.extra.proxy,free=x.kind==='vpn';state.modal=`<div class="modal-backdrop"><section class="form-modal proxy-order-modal"><button data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>${free?'Новое подключение':'Купить Telegram Proxy'}</h2><p>${free?'Бесплатно по вашей активной VPN-подписке. Будет создано отдельное подключение.':`Отдельное подключение на 30 дней, до 2 устройств. Стоимость ${rub(x.price)}. Каждая покупка создаёт новую ссылку.`}</p><p class="proxy-form-error" role="alert" hidden></p>${free?'<button class="checkout-button" data-proxy-issue>Создать бесплатно</button>':`<div class="proxy-payment-choice"><button data-proxy-buy="yookassa" ${x.payments?.yookassa===false?'disabled':''}>Картой или СБП</button><button data-proxy-buy="balance">С баланса · ${rub(state.data.balance)}</button></div>`}</section></div>`;render()}
function proxyPage(){
 const x=state.extra.proxy,header=`<header class="simple-header fo-navigation-header fo-scope"><button class="fo-button fo-icon-button fo-button--flat" data-view="profile" aria-label="Назад">${actionIcon('back')}</button><div><h1>Telegram Proxy</h1></div><button type="button" class="fo-button fo-button--success fo-button--glass fo-button--compact tg-proxy-buy" data-px-purchase="0" ${state.busy?'disabled':''}>${actionIcon('plus-circle')}<span>Купить Proxy</span></button></header>`;
 if(!x)return header+'<div class="fo-empty" role="status">Загружаем подписки…</div>';
 const items=x.items||x.credentials||[];
 const cards=items.map(item=>{const expired=item.status==='expired'||Number.isFinite(Date.parse(item.expires_at))&&Date.parse(item.expires_at)<=Date.now(),active=item.status==='active'&&!expired,valid=item.link&&telegramProxyLink(item.link);return `<article class="tg-proxy-card fo-card${!active?' tg-proxy-card--inactive':''}"><header><span class="tg-proxy-icon">${svg('telegram')}</span><div><div class="tg-proxy-name"><h3>Proxy #${item.id}</h3>${expired?'<span class="fo-status" data-tone="danger">Срок истёк</span>':`<small>${active?'До '+esc(shortDate(item.expires_at)):esc(pxLabels[item.status]==='Активен'?'Неактивна':pxLabels[item.status]||'Неактивна')}</small>`}</div></div></header><div class="tg-proxy-card-actions"><button type="button" class="fo-button fo-button--success fo-button--glass fo-button--compact" data-px-purchase="${item.id}" aria-label="Продлить Telegram Proxy #${item.id}" ${(item.can_renew??['active','expired'].includes(item.status))?'':'disabled'}>${actionIcon('refresh')}<span>Продлить</span></button>${active&&valid?`<button type="button" class="fo-button fo-button--glass fo-button--compact" data-copy-proxy="${item.id}">${actionIcon('copy')}<span>Копировать</span></button><a class="fo-button fo-button--primary fo-button--glass fo-button--compact" href="${esc(item.link)}">${svg('telegram')}<span>Подключить</span></a>`:active?'<p>Ссылка подготавливается.</p>':''}</div></article>`}).join('');
 return `<section class="tg-proxy-page fo-scope">${header}${TelegramProxyHero.render()}<div class="tg-proxy-list">${cards||'<div class="fo-empty">Proxy-подписок пока нет.</div>'}</div></section>`;
}

function infoPage(kind){const x=state.extra.info;if(!x)return pageHeader(kind==='faq'?'Частые вопросы':'Инструкции')+'<div class="support-loading">Загружаем…</div>';const data=kind==='faq'?x.faq:x.instructions;return `<section class="fo-help-page fo-scope">${pageHeader(kind==='faq'?'Частые вопросы':'Инструкции','Помощь')}<div class="fo-help-list">${data.map((item,index)=>item.post_id?`<button type="button" class="fo-row-action fo-help-article" data-post-open="${item.post_id}"><span class="fo-icon-tile">${svg(kind==='faq'?'help':'book')}</span><span><strong>${esc(kind==='faq'?item.question:item.title)}</strong><small>${esc(item.answer||item.text||'Открыть материал')}</small></span>${actionIcon('chevron-right')}</button>`:`<article class="faq"><button class="faq__q" type="button" aria-expanded="false">${esc(kind==='faq'?item.question:item.title)}<i>${actionIcon('chevron-right')}</i></button><div class="faq__a"><div><p>${esc(kind==='faq'?item.answer:item.text).replaceAll('\n','<br>')}</p></div></div></article>`).join('')||'<p class="fo-empty">Материалы готовятся.</p>'}</div></section>`}

function placeholder(title,text){return `<div class="placeholder glass"><h1>${esc(title)}</h1><p>${esc(text)}</p><button class="btn btn-primary" data-view="profile">Вернуться в профиль</button></div>`}
async function loadAdminProxy(){if(isPreview()){state.extra.adminProxy={price:3000,servers:[{id:1,name:'Основной сервер',audience:'all',status:'active',health:'online',active_users:12,connections:18,traffic:'2.4 ГБ'}]};return}const r=await fetch('/api/web/admin/proxy');if(!r.ok)throw Error('Не удалось загрузить серверы');state.extra.adminProxy=await r.json()}
function adminProfilePage(d){const month=state.extra.adminMonth,monthName=new Intl.DateTimeFormat('ru-RU',{month:'long',timeZone:'Europe/Moscow'}).format(new Date());const monthlyWallet=`<button class="profile-wallet-card admin-month-wallet" data-view="balance" aria-label="Выручка за текущий месяц"><span class="profile-wallet-title"><i>${svg('wallet')}</i><small>Баланс · ${esc(monthName)}</small>${actionIcon('chevron-right')}</span><strong>${month?rub(month.stats.revenue):'—'}</strong><span class="admin-month-caption">Выручка от продаж · с 1 числа</span></button>`;const profile=profilePage(d).replace(/<button class="profile-wallet-card"[\s\S]*?<\/button>/,monthlyWallet).replace(/<button class="fo-row-action fo-service-row" data-view="proxy">[\s\S]*?<\/button>/,'').replace(/<button class="fo-row-action fo-service-row" data-view="keys">[\s\S]*?<\/button>/,'').replace('Подключите — Telegram будет работать без VPN','Серверы, клиенты и настройки выдачи');return profile}
function adminProxyDashboardPage(){const x=state.extra.adminProxy,servers=x?.servers||[],online=servers.filter(s=>s.health==='online').length;const stats=[['Серверы',servers.length,'Инфраструктура','server','blue'],['API онлайн',online,online===servers.length&&servers.length?'Все серверы доступны':'Состояние Telemt','status','green'],['Выдача',servers.filter(s=>s.status==='active').length,'Принимают новых клиентов','keys','orange'],['Онлайн',servers.reduce((sum,s)=>sum+s.active_users,0),'Клиенты сейчас','users','purple']];return `<div class="admin-dashboard proxy-management">${pageHeader('Telegram Proxy','Управление сервисом')}<section class="proxy-admin-intro"><div><span class="proxy-admin-eyebrow">ПАНЕЛЬ УПРАВЛЕНИЯ</span><h2>Сеть Telegram Proxy</h2><p>Серверы, подключения и доступ клиентов — в одном месте.</p></div><span class="proxy-health-summary ${online===servers.length&&servers.length?'is-online':'is-neutral'}"><i></i>${online} из ${servers.length} онлайн</span></section><div class="proxy-admin-metrics">${stats.map(([label,value,note,icon,color])=>`<article class="proxy-admin-metric metric-${color}"><span class="proxy-metric-icon">${svg(icon)}</span><small>${label}</small><strong>${value}</strong><span class="proxy-metric-note">${note}</span></article>`).join('')}</div>${adminProxySection()}<section class="proxy-admin-policy"><span>${svg('info')}</span><div><h3>Доступ для клиентов</h3><p>С VPN-подпиской — бесплатно. Без VPN — <strong>${rub(x?.price||0)} за 30 дней.</strong></p></div><button data-proxy-admin-action="admin:p:input:price">Изменить цену</button></section></div>`}
function adminProxySection(){const x=state.extra.adminProxy,q=state.extra.proxyServerQuery||'',servers=(x?.servers||[]).filter(s=>(s.name+' '+s.id).toLowerCase().includes(q.toLowerCase()));return `<section class="data-card admin-proxy-section"><div class="proxy-table-heading"><h2>Серверы</h2><span class="proxy-server-count">${servers.length}</span></div><div class="admin-proxy-actions proxy-dashboard-actions"><button class="proxy-admin-primary" data-proxy-admin-action="admin:p:input:server">${svg('plus-circle')}Подключить сервер</button><button class="proxy-admin-grant" data-proxy-admin-action="admin:p:input:grant">${svg('users')}Выдать клиенту</button><button data-proxy-admin-action="admin:guide:proxy">Настройка Telemt</button></div><form class="proxy-list-search" data-proxy-server-search><input name="q" value="${esc(q)}" placeholder="Поиск по названию или ID сервера" maxlength="100"><button>Найти</button></form><div class="proxy-server-list">${servers.map(s=>`<div class="proxy-server-line"><button class="proxy-server-open" data-proxy-admin-action="admin:p:server:${s.id}"><span class="proxy-online-dot ${s.health==='online'?'online':''}"></span><span class="proxy-server-line-title"><strong>${esc(s.name)}</strong><small>#${s.id} · ${s.status==='active'?'Выдача включена':'Выдача выключена'}</small></span><span class="proxy-server-line-metrics">${s.active_users} онлайн · ${esc(s.traffic)}</span>${actionIcon('chevron-right')}</button><button class="proxy-server-rename" data-proxy-admin-action="admin:p:input:servername:${s.id}" aria-label="Изменить название ${esc(s.name)}">${actionIcon('edit')}</button></div>`).join('')||'<p class="proxy-empty">Серверы не найдены</p>'}</div>${x?.legacy?.length?`<h3>Общие ссылки MTProxy</h3><div class="admin-proxy-actions">${x.legacy.map(e=>`<button data-proxy-admin-action="admin:p:item:${e.id}">${esc(e.name)}</button>`).join('')}</div>`:''}</section>`}
let proxySearchTimer=null,proxySearchRequest=null,proxySearchSequence=0;
async function loadProxyClients(serverId,page=1){const filter={...(state.extra.proxyClientFilter||{q:'',limit:10,status:'all'})},sequence=++proxySearchSequence,view=state.view;proxySearchRequest?.abort();proxySearchRequest=new AbortController();try{const r=await fetch('/api/web/admin/proxy/clients?server_id='+serverId+'&q='+encodeURIComponent(filter.q)+'&limit='+filter.limit+'&page='+page+'&status='+encodeURIComponent(filter.status||'all'),{signal:proxySearchRequest.signal});const x=await r.json();if(sequence!==proxySearchSequence||state.view!==view)return;if(!r.ok)throw Error(x.detail||'Не удалось загрузить клиентов');const input=document.activeElement,focused=input?.matches('[data-proxy-client-search] input'),start=focused?input.selectionStart:null,end=focused?input.selectionEnd:null;state.extra.adminProxyScreen=x;state.view='admin-proxy-server';render();if(focused){const next=app.querySelector('[data-proxy-client-search] input');next?.focus({preventScroll:true});next?.setSelectionRange(start,end)}}catch(e){if(e.name!=='AbortError')throw e}}
async function loadProxyCustomer(id){const sequence=++proxySearchSequence;proxySearchRequest?.abort();clearTimeout(proxySearchTimer);const r=await fetch('/api/web/admin/proxy/customer/'+id),x=await r.json();if(sequence!==proxySearchSequence)return;if(!r.ok)throw Error(x.detail||'Не удалось открыть клиента');state.extra.proxyCustomer=x;state.extra.adminProxyScreen=x;state.view='admin-proxy-server';render()}
function proxyCustomerPage(x){const u=x.user,active=x.keys.filter(k=>k.status==='active'&&daysLeft(k.expires_at)>0);return `<div class="admin-dashboard proxy-management proxy-customer-page">${proxyDetailHeader('Клиент','admin:p:users:'+(state.extra.proxyClientServer||x.keys[0]?.server_id||1)+':0')}<section class="data-card proxy-customer-identity"><span class="proxy-customer-avatar"><span>${esc(u.name.slice(0,1))}</span>${u.avatar?`<img src="${esc(u.avatar)}" alt="" data-proxy-customer-avatar>`:''}</span><div><h2>${esc(u.name)}</h2><p>${esc(u.username?'@'+u.username:'Telegram-клиент')}</p><small>${esc(u.freeman_id||'')} · ${esc(u.telegram_id||'—')}</small></div><span class="proxy-customer-count">${active.length} активных</span></section><div class="admin-proxy-actions proxy-customer-actions"><button data-proxy-customer-issue>Выдать новый</button>${x.targets?.some(t=>active.some(k=>k.server_id!==t.id))?'<button data-proxy-customer-move>Перенести все ключи</button>':''}${u.telegram_id?`<a class="customer-contact-action" href="tg://user?id=${u.telegram_id}">Связаться с клиентом</a>`:''}</div>${x.notice?`<p class="proxy-detail-note">${esc(x.notice)}</p>`:''}<section class="data-card proxy-customer-keys"><div class="proxy-clients-heading"><h2>Прокси-ключи</h2><span>${x.keys.length}</span></div>${x.keys.map(k=>`<div class="admin-subscription-line"><div><strong>Ключ #${k.id} · ${esc(k.server)}</strong><small>${k.kind==='vpn'?'С VPN':k.kind==='paid'?'Отдельный':'Не указан'} · ${esc(k.status)} · до ${esc(shortDate(k.expires_at))} · ${esc(k.traffic)} · IP ${k.ips}</small></div><button class="admin-small-action" data-proxy-admin-action="admin:p:cred:${k.id}">Открыть</button></div>`).join('')||'<p>Прокси-ключей пока нет.</p>'}</section></div>`}
function proxyClientList(x){return `<div class="proxy-clients-heading"><h2>Клиенты</h2><span>${x.total} записей</span></div><div class="proxy-status-filters">${[['all','Все'],['active','Активные'],['disabled','Заблокированные'],['expired','Истёкшие'],['migrated','Заменённые']].map(([v,l])=>`<button class="${(x.status||'all')===v?'active':''}" data-proxy-status="${v}">${l}</button>`).join('')}</div><form class="proxy-list-search proxy-client-search" data-proxy-client-search="${x.server_id}"><input name="q" value="${esc(x.q||'')}" maxlength="100" placeholder="Имя, @username, Freeman ID или ключ"><label class="proxy-limit-control"><select name="limit" aria-label="Записей на странице">${[10,25,50,100].map(n=>`<option value="${n}" ${x.limit===n?'selected':''}>${n}</option>`).join('')}</select><span aria-hidden="true">⌄</span></label></form><div class="admin-table-scroll proxy-table-viewport"><table class="admin-server-table proxy-records-table"><thead><tr><th>Клиент / ключ</th><th>Первый ключ</th><th>Доступ</th><th>Статус / до</th><th>Трафик</th><th>IP / лимит</th><th>Соединения</th><th>Проверка</th></tr></thead><tbody>${x.clients.map(c=>`<tr data-proxy-customer="${c.user_id}"><td><button class="proxy-client-name" data-proxy-customer="${c.user_id}"><strong>${esc(c.name)}</strong><small>${esc(c.freeman_id||c.telegram_id||'—')} · ключей ${c.key_count??1}</small><small class="proxy-desktop-cell">${esc(c.username?'@'+c.username:'')} · ${esc(c.remote_username)}</small></button></td><td class="proxy-desktop-cell">${esc(shortDate(c.created_at))}</td><td class="proxy-desktop-cell">${c.kind==='vpn'?'С VPN-подпиской':c.kind==='paid'?'Отдельный доступ':'Не указан'}</td><td><span class="proxy-state ${c.status==='active'&&daysLeft(c.expires_at)>0?'state-green':'state-gray'}">${c.status==='active'&&daysLeft(c.expires_at)>0?'Активен':c.status==='disabled'?'Остановлен':c.status==='migrated'?'Заменён':'Неактивен'}</span><small class="proxy-desktop-cell">${esc(shortDate(c.expires_at))}</small></td><td class="proxy-desktop-cell">${esc(c.traffic)}</td><td class="proxy-desktop-cell">${c.ips} / ${esc(c.ip_limit)}</td><td class="proxy-desktop-cell">${c.connections}</td><td class="proxy-desktop-cell">${c.last_sync?esc(shortDate(c.last_sync)):'—'}</td></tr>`).join('')||'<tr><td colspan="8">Ничего не найдено</td></tr>'}</tbody></table></div><div class="proxy-list-pagination"><button data-proxy-client-page="${x.page-1}" ${x.page<=1?'disabled':''}>Назад</button><span>${x.page} / ${Math.max(1,Math.ceil(x.total/x.limit))}</span><button data-proxy-client-page="${x.page+1}" ${x.page*x.limit>=x.total?'disabled':''}>Далее</button></div>`}
function proxyDetailHeader(title,back='admin:p:home'){return FreemanComponents.adminHeader({title,description:'Telegram Proxy',back:`<button class="fo-button fo-icon-button" data-proxy-admin-action="${esc(back)}" aria-label="Назад">${actionIcon('back')}</button>`})}
function proxyCompactFacts(tables){const rows=tables.flat().filter(r=>r[0]!=='Показатель'),important=['Ключ','Сервер','Статус','Клиент','Трафик','Действует до','Уникальные IP'],main=rows.filter(r=>important.includes(r[0])),other=rows.filter(r=>!important.includes(r[0]));return `<div class="proxy-key-facts">${proxyDetailsTable(main)}</div>${other.length?`<details class="proxy-key-extra"><summary>Подробная информация</summary>${proxyDetailsTable(other)}</details>`:''}`}
function proxyDetailsTable(table){return `<dl class="proxy-facts">${table.filter((r,i)=>!(i===0&&r[0]==='Показатель')).map(r=>`<div><dt>${esc(r[0])}</dt><dd>${esc(r.slice(1).join(' · '))}</dd></div>`).join('')}</dl>`}
function proxyGuidePage(x){return `<div class="admin-dashboard proxy-management proxy-guide">${proxyDetailHeader(x.title,x.back)}<section class="proxy-guide-intro"><h2>Подключение сервера</h2><p>Настройте Telemt, затем добавьте его API в общую систему сайта и бота.</p></section>${x.steps.map((s,i)=>`<section class="data-card proxy-guide-step"><header><span>${i+1}</span><h2>${esc(s.title)}</h2></header><p>${esc(s.text).replace(/\n\n/g,'</p><p>')}</p>${s.code?`<div class="proxy-code-window"><header><span class="proxy-window-dots"><i></i><i></i><i></i></span><small>${esc(s.code_label||'Терминал')}</small><button data-proxy-copy-code="${i}" aria-label="Скопировать команду">${actionIcon('copy')}<span>Копировать</span></button></header><pre><code>${esc(s.code)}</code></pre></div>`:''}</section>`).join('')}${x.source?`<p class="proxy-detail-note"><a href="${esc(x.source)}" target="_blank" rel="noopener">Документация Telemt</a></p>`:''}<button class="proxy-guide-connect" data-proxy-admin-action="admin:p:input:server">Подключить сервер</button></div>`}
function adminProxyServerPage(){const x=state.extra.adminProxyScreen;if(!x)return '<div class="support-loading">Загружаем сервер…</div>';if(x.kind==='guide')return proxyGuidePage(x);if(x.kind==='customer')return proxyCustomerPage(x);if(x.credential_id&&state.extra.proxyCustomer?.keys.some(k=>k.id===x.credential_id))x.back='customer:'+state.extra.proxyCustomer.user.id;const flat=(x.rows||[]).flat(),buttons=flat.filter(b=>!b.action.startsWith('admin:p:newproxy:')&&!b.action.startsWith('url:tg://')&&b.action!==x.back&&!/← Назад|К серверу|К серверам|К списку|К настройкам|← Отмена/.test(b.label)&&!(x.kind==='clients'&&(b.action.startsWith('admin:p:cred:')||b.action.startsWith('url:'))));let content='';if(x.kind==='clients'){content=proxyClientList(x)}else if(x.tables?.length){content=x.credential_id?proxyCompactFacts(x.tables):x.tables.map(proxyDetailsTable).join('')+(x.note?`<p class="proxy-detail-note">${esc(x.note)}</p>`:'')}else{const lines=x.text.split('\n').filter(Boolean),pairs=lines.slice(1).filter(l=>/^[^:]{1,60}: .+/.test(l));content=pairs.length>=3?proxyDetailsTable(pairs.map(l=>{const i=l.indexOf(':');return [l.slice(0,i),l.slice(i+1).trim()]})):`<div class="proxy-detail-message"><p>${esc(x.text).replace(/\n\n/g,'</p><p>')}</p></div>`}return `<div class="admin-dashboard proxy-management proxy-server-detail">${proxyDetailHeader(x.title||'Управление сервером',x.back)}<section class="data-card">${content}${x.error?`<p class="proxy-detail-error">${esc(x.error)}</p>`:''}${x.diagnostic?`<details class="proxy-diagnostic-help" open><summary>Настройка записи конфигурации</summary><p>${esc(x.diagnostic)}</p></details>`:''}<div class="admin-proxy-actions">${buttons.map(b=>b.action.startsWith('url:')?`<a class="admin-proxy-link" href="${esc(b.action.slice(4))}">${esc(b.label)}</a>`:`<button data-proxy-admin-action="${esc(b.action)}" class="${x.options?.[b.action]?.style==='danger'?'proxy-action-danger':''}">${esc(b.label)}</button>`).join('')}</div></section></div>`}
let proxyRecipientTimer=null,proxyRecipientRequest=null;
function proxyGrantModal(){const servers=(state.extra.adminProxy?.servers||[]).filter(s=>s.status==='active'&&s.audience!=='vpn');return `<div class="modal-backdrop"><form class="form-modal proxy-grant-modal" data-proxy-grant><button type="button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>Выдать Telegram Proxy</h2><label>Клиент или приглашение<input name="identity" data-proxy-recipient autocomplete="off" maxlength="100" placeholder="Имя, username, Freeman ID, Telegram ID, email"></label><div class="proxy-recipient-results" aria-live="polite"></div><p class="proxy-grant-help">Выберите клиента из подсказок. Оставьте поле пустым, чтобы создать одноразовую ссылку для нового получателя.</p><label>Сервер<select name="server_id" required>${servers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></label><div class="proxy-grant-fields"><label>Дней<input name="days" type="number" value="30" min="1" max="3650" required></label><label>Лимит IP<input name="ip" type="number" value="2" min="2" max="100" required></label><label>Лимит TCP<input name="tcp" type="number" value="2" min="2" max="1000" required></label></div><p class="login-form-error" hidden></p><button class="checkout-button" type="submit" ${servers.length?'':'disabled'}>Создать приглашение</button>${servers.length?'':'<p>Для приглашений нужен активный сервер группы «Все» или «Платный доступ».</p>'}</form></div>`}
function proxyInviteModal(x){const message='Вам доступен Telegram Proxy Freeman. Чтобы получить подключение, перейдите в Telegram-бот: '+x.link;state.extra.proxyInvite={...x,message};return `<div class="modal-backdrop"><section class="form-modal proxy-invite-modal"><button data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>Приглашение готово</h2><p>${esc(x.server)} · ${x.days} дней доступа</p><div class="proxy-invite-message">${esc(message)}</div><p class="proxy-grant-help">Ссылка действует 3 дня, закрепляется за первым получателем. Срок прокси начнётся после получения в боте.</p><div class="admin-proxy-actions"><button data-proxy-invite-copy>Скопировать сообщение</button><a href="https://t.me/share/url?url=${encodeURIComponent(x.link)}&text=${encodeURIComponent('Вам доступен Telegram Proxy Freeman. Для получения откройте нашего Telegram-бота.')}" target="_blank" rel="noopener">Поделиться в Telegram</a></div></section></div>`}
function adminProxyFields(action){const kind=action.split(':')[3],field=(label,name,type='text',value='',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${value}" required autocomplete="off" ${extra}></label>`,group='<label>Группа выдачи<select name="group"><option value="all">Все клиенты с доступом</option><option value="vpn">С VPN-подпиской</option><option value="paid">Платный прокси</option></select></label>';let fields=[];if(kind==='server'||kind==='serveredit')fields=[field('Название сервера','name'),field('URL Telemt API','url','url'),group,field('Приоритет','priority','number','100','min="1" max="999"'),field('Лимит IP','ip','number','2','min="2" max="100"'),field('Лимит TCP','tcp','number','2','min="2" max="1000"'),field('Authorization','auth','password')];else if(kind==='grant')fields=[field('Freeman ID, Telegram ID или email','identity'),field('Срок, дней','days','number','30','min="1" max="3650"'),field('Лимит IP','ip','number','2','min="2" max="100"'),field('Лимит TCP','tcp','number','2','min="2" max="1000"')];else if(kind==='price')fields=[field('Цена за 30 дней, ₽','price','number','','min="0.01" max="1000000" step="0.01"')];else if(kind==='servername'||kind==='name')fields=[field('Название','name','text',esc(state.extra.adminProxy?.servers?.find(s=>s.id===Number(action.split(':')[4]))?.name||''),'maxlength="80"')];else if(kind==='serverpriority')fields=[field('Приоритет','priority','number','','min="1" max="999"')];else if(kind==='serverlimits')fields=[field('Лимит IP','ip','number','2','min="2" max="100"'),field('Лимит TCP','tcp','number','2','min="2" max="1000"')];else if(kind==='serverapi')fields=[field('URL API','url','url'),field('Authorization','auth','password')];else fields=[field('Ссылка MTProxy','value')];return fields.join('')}
async function proxyAdminAction(action,text=''){++proxySearchSequence;proxySearchRequest?.abort();clearTimeout(proxySearchTimer);if(action.startsWith('customer:'))return loadProxyCustomer(Number(action.split(':')[1]));if(action.startsWith('admin:p:users:')&&!isPreview()){const serverId=Number(action.split(':')[3]);if(state.extra.proxyClientServer!==serverId){state.extra.proxyClientFilter={status:state.extra.adminProxyScreen?.status||'all',q:'',limit:10,status:'all'};state.extra.proxyClientServer=serverId}await loadProxyClients(serverId);return}if(action==='admin:p:home'){state.view='admin-proxy';await loadAdminProxy();render();return}if(action==='admin:p:input:grant'&&!text){state.modal=proxyGrantModal();render();return}if(action.startsWith('admin:p:input:')&&!text){const formats={server:'Название | https://API-адрес | all (либо vpn/paid) | приоритет | IP лимит | TCP лимит | Authorization',grant:'Freeman ID, Telegram ID или email | дней | IP лимит | TCP лимит',price:'Цена за 30 дней, ₽',servername:'Название сервера',serverpriority:'Приоритет 1–999',serverlimits:'Лимит IP | Лимит TCP',serverapi:'https://API-адрес | Authorization'};state.modal=`<div class="modal-backdrop"><form class="form-modal" data-admin-proxy-input="${esc(action)}"><button type="button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>Настройка Telegram Proxy</h2>${adminProxyFields(action)}<p class="login-form-error" hidden></p><button type="submit" class="checkout-button">Сохранить</button></form></div>`;render();return}const destructive=/:(serverdelete|creddelete|delete|moveapply|moveallapply|newproxy|replaceproxy|customermove):/.test(action);if(destructive&&!await FreemanUI.confirm('Подтвердить операцию? Она изменит доступ клиентов.'))return;if(isPreview()){if(text)return say('Предпросмотр: настройки сервера не изменяются');const id=Number(action.split(':')[3]);state.extra.adminProxyScreen={text:'Основной сервер\nВыдача: включена\nTelemt API: online\nЗапись конфигурации: без известных ошибок\nОнлайн клиентов: 12\nСоединения: 18\nТрафик: 2.4 ГБ',rows:[[{label:'Клиенты и ключи',action:'admin:p:users:1:0'}],[{label:'Диагностика',action:'admin:p:diagnose:1'}],[{label:'Синхронизация',action:'admin:p:sync:1'}],[{label:'Перенести клиентов',action:'admin:p:moveall:1'}],[{label:'Настройки сервера',action:'admin:p:settings:1'}],[{label:'Выключить выдачу',action:'admin:p:servertoggle:1'}],[{label:'Удалить сервер',action:'admin:p:serverdeleteconfirm:1'}],[{label:'К серверам',action:'admin:p:home'}]]};state.view='admin-proxy-server';render();return}const r=await fetch('/api/web/admin/proxy/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,text,confirmed:destructive,request_id:crypto.randomUUID()})});const result=await r.json();if(!r.ok)throw Error(result.detail||'Операция не выполнена');state.modal=null;if(result.kind==='customer-moved'){await loadProxyCustomer(result.user_id);state.extra.proxyCustomer.notice=`Перенесено: ${result.moved}. Уже на сервере: ${result.skipped}. Ошибок: ${result.failed}. ${result.errors.join(' · ')}`;render();return}if(result.kind==='created'){if(state.extra.proxyCustomer)await loadProxyCustomer(state.extra.proxyCustomer.user.id);await proxyAdminAction('admin:p:cred:'+result.credential_id);if(result.warning)say(result.warning);return}if(result.kind==='home'){state.view='admin-proxy';await loadAdminProxy();render();return}if(!result.back)result.back='admin:p:home';state.extra.adminProxyScreen=result;state.view='admin-proxy-server';render()}
let adminLiveTimer=null,adminLiveRequest=null,adminLiveSequence=0;
function adminListView(){return state.view==='admin-servers'&&state.extra.infrastructureTab==='subscriptions'?'admin-keys':state.view}
async function loadAdminList(view=adminListView(),page=1){const filter=state.extra[view+'Filter']||{q:'',status:'all',limit:10},seq=++adminLiveSequence;adminLiveRequest?.abort();adminLiveRequest=new AbortController();if(view==='admin-clients'){state.extra.crmListError='';if(!state.extra[view+'List']){state.extra.crmListLoading=true;render()}}try{const path=view==='admin-keys'?'keys':'users',r=await fetch('/api/web/admin/'+path+'/search',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...filter,q:filter.q,status:filter.status,origin:filter.origin||'all',devices:filter.devices||'all',expiry:Number(filter.expiry||0),tariff_id:filter.tariff_id?Number(filter.tariff_id):null,server_id:filter.server_id?Number(filter.server_id):null,customer_state:filter.customer_state||'all',expired_range:filter.expired_range||'all',device_limit:filter.device_limit?Number(filter.device_limit):null,limit:filter.limit,page}),signal:adminLiveRequest.signal}),x=await r.json();if(seq!==adminLiveSequence||!(state.view===view||(view==='admin-keys'&&state.view==='admin-servers'&&state.extra.infrastructureTab==='subscriptions')))return;if(!r.ok)throw Error(x.detail||'Не удалось загрузить список');const input=document.activeElement,focused=input?.matches('[data-admin-live-search]'),start=focused?input.selectionStart:null,end=focused?input.selectionEnd:null;state.extra[view+'List']=x;if(view==='admin-clients')state.extra.crmListLoading=false;render();if(focused){const next=app.querySelector('[data-admin-live-search]');next?.focus({preventScroll:true});next?.setSelectionRange(start,end)}}catch(e){if(e.name!=='AbortError'){if(view==='admin-clients'){state.extra.crmListLoading=false;state.extra.crmListError=e.message;render()}else say(e.message)}}}
async function loadAdminKeys(){return loadAdminList('admin-keys')}
function adminListControls(view,x){const filter=state.extra[view+'Filter']||{q:'',status:'all',limit:10};return `<div class="proxy-status-filters">${(view==='admin-keys'?[['all','Все'],['active','Активные'],['blocked','Остановленные'],['expired','Истёкшие']]:[['all','Все'],['active','Активные'],['blocked','Заблокированные']]).map(([v,l])=>`<button data-admin-list-status="${v}" class="${filter.status===v?'active':''}">${l}</button>`).join('')}</div><div class="proxy-status-filters admin-origin-filters"><button data-admin-origin="all" class="${!filter.origin||filter.origin==='all'?'active':''}">Все клиенты</button><button data-admin-origin="external" class="${filter.origin==='external'?'active':''}">Внешние клиенты</button></div><form class="proxy-list-search proxy-client-search" data-admin-list-form><input data-admin-live-search value="${esc(filter.q)}" placeholder="Имя, ID, username, email${view==='admin-keys'?', ключ':''}" maxlength="100"><label class="proxy-limit-control"><select data-admin-list-limit aria-label="Записей на странице">${[10,25,50,100].map(n=>`<option value="${n}" ${filter.limit===n?'selected':''}>${n}</option>`).join('')}</select><span aria-hidden="true">⌄</span></label></form>`}
function adminListPagination(x){return x?`<div class="proxy-list-pagination"><button data-admin-list-page="${x.page-1}" ${x.page<=1?'disabled':''}>Назад</button><span>${x.page} / ${Math.max(1,Math.ceil(x.total/x.limit))} · ${x.total} записей</span><button data-admin-list-page="${x.page+1}" ${x.page*x.limit>=x.total?'disabled':''}>Далее</button></div>`:''}

function adminAvatar(name,url,componentClass=''){return FreemanComponents.avatar({name,avatar:url},{className:'admin-avatar-circle '+componentClass})}
let adminKeyLoadSequence=0;
async function openAdminKey(id,{customerId=null}={}){const sequence=++adminKeyLoadSequence,routeSequence=routeLoadSequence;const r=await fetch('/api/web/admin/keys/'+id),x=await r.json();if(sequence!==adminKeyLoadSequence||routeSequence!==routeLoadSequence)return;if(!r.ok)throw Error(x.detail||'Ключ недоступен');if(customerId!==null&&Number(x.user.id)!==Number(customerId))throw Error('Владелец ключа изменился. Обновите список.');if(state.view==='support'&&state.supportTicket)state.extra.adminKeySupportTicket=state.supportTicket;else if(state.view!=='admin-key')state.extra.adminKeySupportTicket=null;state.extra.adminKey=x;state.view='admin-key';render()}
function adminKeyActions(k,compact=false){return `<div class="admin-key-actions ${compact?'is-compact':''}"><button class="key-renew" data-admin-key-operation="extend" data-key-id="${k.id}">Продлить</button><button data-admin-key-operation="${k.status==='active'?'block':'unblock'}" data-key-id="${k.id}">${k.status==='active'?'Остановить':'Включить'}</button>${!compact?`<button data-admin-key-operation="rename" data-key-id="${k.id}">Переименовать</button><button data-admin-key-operation="assign" data-key-id="${k.id}">Передать клиенту</button><button data-admin-key-operation="reset_devices" data-key-id="${k.id}">Сбросить устройства</button>`:''}${k.mode!=='mock'?`<button data-admin-key-operation="rotate" data-key-id="${k.id}">Перевыпустить</button>`:''}<button class="key-danger" data-admin-key-operation="delete" data-key-id="${k.id}">Удалить</button></div>`}
function adminKeyPage(){
 const x=state.extra.adminKey;if(!x)return '';
 const k=x.key,a=x.actions||{},id=Number(k.id),ticket=Number(state.extra.adminKeySupportTicket);
 const button=(label,attributes,tone='')=>`<button type="button" class="fo-button fo-button--compact ${tone}" ${attributes}>${label}</button>`;
 const op=(action,label,tone)=>button(label,`data-admin-key-operation="${action}" data-key-id="${id}"`,tone);
 const back=ticket>0?`data-support-return="${ticket}"`:'data-view="admin-keys"';
 const [status,label]=customerSubscriptionStatus(k);
 const addon=k.antig_active===true?'Антиглушилка включена':k.antig_active===false?'Антиглушилка выключена':'';
 return `<section class="keys-manager fo-scope">${FreemanComponents.adminHeader({title:k.name||'Подписка #'+id,description:'Ключ #'+id,back:`<button type="button" class="fo-button fo-icon-button" ${back} aria-label="${ticket>0?'Вернуться в чат':'Вернуться к подпискам'}">${actionIcon('chevron-left')}</button>`})}
 <section class="fo-key-registry"><div class="fo-subscription-detail">
 <dl class="customer-key-facts">
 ${[['Статус',label],['Действует до',k.expires_at?shortDate(k.expires_at):'—'],['Лимит устройств',x.device_limit===0?'Без лимита':x.device_limit??'—'],['Клиент',x.user.name||'—'],['E-mail аккаунта',x.user.email||'Не привязан'],['Антиглушилка',addon||'Нет данных']].map(([title,value])=>`<div><dt>${title}</dt><dd>${esc(value)}</dd></div>`).join('')}
 </dl>
 <div class="fo-subscription-toolbar">
 ${a.copy?button(k.connection_url?'Копировать ссылку':'Копировать конфигурацию',`data-keys-copy="${id}"`):''}
 ${a.devices?button('Устройства',`data-keys-devices="${id}"`):''}
 ${a.renew?op('extend','Продлить','fo-button--success fo-button--glass'):''}
 ${x.can_assign?op('assign','Передать клиенту'):''}
 ${k.mode==='vless'&&['active','expiring'].includes(status)&&k.antig_active===false&&state.data.antig_addon_available===true&&state.data.payments?.owner_free?button('Добавить антиглушилку',`data-key-antig="${id}"`):''}
 ${k.mode==='vless'&&['active','expiring'].includes(status)&&k.antig_active===true&&state.data.payments?.owner_free?button('Отключить антиглушилку',`data-admin-antig-disable="${id}"`):''}
 ${button('Профиль клиента',`data-admin-user="${Number(x.user.id)}"`)}
 <details class="fo-subscription-actions" data-fo-details><summary class="fo-button fo-button--compact">Ещё</summary><div class="fo-menu" data-fo-popup="menu">
 ${op('rename','Переименовать')}${x.can_rotate?op('rotate','Перевыпустить'):''}${a.block?op('block','Заблокировать'):''}${a.unblock?op('unblock','Разблокировать'):''}${a.delete?op('delete','Удалить подписку','fo-button--danger'):''}
 </div></details>
 </div></div></section></section>`;
}

function adminKeyActionModal(id,action){if(action==='extend')return flexibleRenewModal(id);if(action==='reset_devices')return keyResetConfirmModal(id);const labels={rename:'Переименовать ключ',extend:'Добавить дни',assign:'Передать ключ клиенту',block:'Остановить ключ',unblock:'Включить ключ',rotate:'Перевыпустить ключ',delete:'Удалить ключ',reset_devices:'Сбросить устройства'},needs=['rename','extend','assign'].includes(action);return `<div class="modal-backdrop"><form class="form-modal" data-admin-key-form data-key-id="${id}" data-operation="${action}"><button type="button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button><h2>${action==='rotate'?'Перезапустить подписку':action==='delete'?'Удалить подписку?':labels[action]} #${id}</h2>${needs?`<label>${action==='rename'?'Новое название':action==='extend'?'Количество дней':'ID клиента из списка'}<input name="value" required ${action==='rename'?'maxlength="100"':'type="number" min="1"'} ${action==='extend'?'max="3650" value="30"':''}></label>`:''}<p>${action==='reset_devices'?'Все устройства этой подписки будут отвязаны. Блокировка администратором сохраняется.':action==='delete'?'Ключ будет отозван и удалён из списка. Оставшийся срок не возвращается.':action==='rotate'?'Старая конфигурация перестанет работать. Устройства потребуется подключить заново.':action==='assign'?'Ключ и связанная подписка переходят другому клиенту. История платежей остаётся у прежнего владельца.':'Изменение применяется к выбранному ключу и связанной подписке.'}</p><p class="login-form-error" hidden></p><button type="button" data-close-modal>Отмена</button><button class="checkout-button" type="submit">Подтвердить</button></form></div>`}
function keysRow(item){
 const expiry=new Date(item.expires_at),valid=!!item.expires_at&&Number.isFinite(expiry.getTime()),ms=expiry-Date.now(),hours=Math.max(0,Math.floor(ms/3600000)),days=Math.floor(hours/24);
 const stopped=['blocked','disabled','paused'].includes(item.status),expired=item.status==='expired'||(valid&&ms<=0),live=item.status==='active'&&!expired;
 const status=stopped?'Остановлена':expired?'Истекла':live?'Активна':'Недоступна',tone=stopped?'neutral':expired?'warning':live?'success':'neutral';
 const remaining=!valid?'Срок не указан':ms<=0?'Срок истёк':days?days+' дн.':hours?hours+' ч.':'Менее часа';
 const title=String(item.name||'').trim(),name=title&&!/^подписка$/i.test(title)?title:'Подписка #'+item.id;
 const months=Number(item.duration_months||item.months||0),period=months===12?'1 год':months===24?'2 года':months?months+' '+(months===1?'месяц':months<5?'месяца':'месяцев'):'';
 const count=item.device_count??'—',limit=item.device_limit===0?'∞':item.device_limit??'—',deviceHint=item.device_count==null?'Точное число устройств ещё не подтверждено':'Подключено устройств: '+item.device_count+' из '+limit;
 const open=(state.extra.subscriptionExpanded||[]).includes(item.id);
 return `<details class="fo-subscription-record" data-subscription-record="${item.id}" data-record-id="${item.id}" ${open?'open':''}><summary class="fo-subscription-summary fo-disclosure" aria-label="${esc(name)} · ${esc(item.owner||'Клиент')} · ${status}"><span class="fo-subscription-client">${adminAvatar(item.owner,item.avatar_url,'fo-avatar')}<span><span>${esc(item.owner||'Клиент')}</span><small>${esc(displayFreemanId(item.freeman_id||''))||'ID не назначен'}</small></span></span><span class="fo-subscription-title"><span>${esc(name)}</span><small>#${item.id}${period?' · '+esc(period):''}</small></span><span class="fo-subscription-status"><span class="fo-status" data-tone="${tone}">${status}</span></span><span class="fo-subscription-expiry"><span>${valid?esc(expiry.toLocaleDateString('ru-RU',{day:'2-digit',month:'2-digit',year:'2-digit'})):'—'}</span><small>${remaining}</small></span><span class="fo-subscription-devices" title="${esc(deviceHint)}">${keysIcon('devices')}<span>${count} / ${limit}</span></span><span class="fo-subscription-chevron" aria-hidden="true">${actionIcon('chevron-down')}</span></summary><div class="fo-subscription-detail"><div class="fo-subscription-connection"><span>Ссылка подключения</span>${item.connection_url?`<code>${esc(item.connection_url)}</code>`:'<p>Ссылка ещё не выдана</p>'}</div><div class="fo-subscription-toolbar"><button class="fo-button fo-button--compact" data-admin-key="${item.id}">Открыть карточку</button><button class="fo-button fo-button--compact" data-admin-user="${item.user_id}">Клиент</button>${item.connection_url?`<button class="fo-button fo-button--compact" data-keys-copy="${item.id}">${actionIcon('copy')}Копировать</button>`:''}${live&&item.mode!=='mock'?`<button class="fo-button fo-button--compact" data-admin-key-operation="assign" data-key-id="${item.id}">Передать</button>`:''}${live&&item.mode==='vless'&&item.antig_active===false&&state.data.antig_addon_available===true&&state.data.payments?.owner_free?`<button class="fo-button fo-button--compact" data-key-antig="${item.id}">${actionIcon('shield-check')}Добавить антиглушилку</button>`:''}<button class="fo-button fo-button--compact" data-keys-devices="${item.id}">${keysIcon('devices')}Устройства</button><button class="fo-button fo-button--success fo-button--glass fo-button--compact" data-admin-key-operation="extend" data-key-id="${item.id}">Продлить</button><details class="fo-subscription-actions" data-fo-details><summary class="fo-button fo-icon-button fo-button--compact" aria-label="Другие действия подписки ${item.id}">⋯</summary><div class="fo-menu" data-fo-popup="menu"><button class="fo-button" data-admin-key-operation="rename" data-key-id="${item.id}">Переименовать</button><button class="fo-button" data-admin-key-operation="assign" data-key-id="${item.id}">Передать клиенту</button>${item.mode!=='mock'?`<button class="fo-button" data-admin-key-operation="${live?'block':'unblock'}" data-key-id="${item.id}">${live?'Остановить':'Включить'}</button>${live?`<button class="fo-button" data-admin-key-operation="rotate" data-key-id="${item.id}">Перевыпустить</button>`:''}`:''}${item.return_customer?`<button class="fo-button" data-key-offer="${item.id}">Предложение клиенту</button>`:''}<button class="fo-button fo-button--danger" data-admin-key-operation="delete" data-key-id="${item.id}">Удалить подписку</button></div></details></div></div></details>`;
}
document.addEventListener('toggle',e=>{const record=e.target;if(!record.matches?.('[data-subscription-record]')||!record.isConnected)return;const id=Number(record.dataset.subscriptionRecord),open=new Set(state.extra.subscriptionExpanded||[]);if(record.open)open.add(id);else open.delete(id);state.extra.subscriptionExpanded=[...open]},true);

function adminKeysPage(){
  const x=state.extra['admin-keysList'],f=state.extra['admin-keysFilter']||{q:'',status:'all',limit:10};
  const field=(name,label,options)=>`<label class="fo-field"><span class="fo-field-label">${label}</span><select class="fo-select" data-keys-filter-field="${name}" aria-label="${esc(label)}">${options.map(([v,t])=>`<option value="${v}" ${String(f[name]??'')===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
  const active=Object.entries(f).filter(([k,v])=>!['q','limit','status'].includes(k)&&v&&v!=='all').length;
  return `<section class="fo-key-registry fo-scope fo-page" data-fo-surface><button class="fo-button fo-button--plain" data-nav-back data-view="admin-servers" aria-label="Назад">${actionIcon('back')}Назад</button><header class="fo-registry-heading"><div><h1>${f.server_id?'Подписки панели':'Подписки'}</h1><p>Подписки и подключения клиентов</p></div><button class="fo-button fo-button--success" data-admin-vpn-grant>+ Выдать подписку</button></header><div class="fo-registry-toolbar"><label class="fo-input-group">${svg('search')}<input class="fo-input" data-admin-live-search value="${esc(f.q)}" maxlength="4096" placeholder="Клиент, ID, название или ссылка…" aria-label="Поиск подписок"></label><button class="fo-button" data-keys-filter aria-expanded="${!!state.extra.keysFilterOpen}">${keysIcon('filter')}Фильтры${active?' · '+active:''}</button>${field('status','Статус',[['all','Все'],['active','Активные'],['soon','Скоро истекают'],['expired','Истёкшие'],['blocked','Остановленные']])}<details data-fo-details><summary class="fo-button fo-icon-button" aria-label="Действия со списком">⋯</summary><div class="fo-menu" data-fo-popup="menu"><button class="fo-button" data-reset-blocked-devices data-reset-all-keys>Сбросить устройства всех ключей</button></div></details></div>${state.extra.keysFilterOpen?`<section class="fo-filter-grid fo-card" aria-label="Фильтры подписок">${field('devices','Подключения',[['all','Любые'],['none','Без подключённых устройств'],['available','Есть свободные места'],['partial','Используется, есть места'],['limit','Лимит занят'],['unknown','Данные ещё не получены']])}${field('device_limit','Максимум устройств',[['','Любой'],...(x?.device_limits||[]).map(n=>[n,n+' '+deviceWord(n)])])}${field('tariff_id','Тариф',[['','Все тарифы'],...(x?.tariffs||[]).map(t=>[t.id,t.name])])}${field('server_id','Сервер',[['','Все серверы'],...(x?.servers||[]).map(s=>[s.id,s.name])])}${field('customer_state','Клиенты',[['all','Все'],['active','Есть активная подписка'],['inactive','Нет активной подписки']])}${field('expired_range','Истекла',[['all','Любой период'],['7-30','7–30 дней назад'],['30-90','30–90 дней назад'],['90+','Более 90 дней назад']])}${field('origin','Источник',[['all','Все клиенты'],['internal','Зарегистрированные'],['external','Внешние']])}<button class="fo-button" data-keys-filter-reset>Сбросить</button></section>`:''}<div class="fo-subscription-head" aria-hidden="true"><span>Клиент</span><span>Подписка</span><span>Статус</span><span>Действует до</span><span>Устройства</span><span></span></div><div class="fo-key-list">${(x?.items||[]).map(keysRow).join('')||'<p class="fo-empty">Подписок по этим условиям нет</p>'}</div>${x?`<footer class="fo-registry-pagination"><small>Показано ${x.total?(x.page-1)*x.limit+1:0}–${Math.min(x.total,(x.page-1)*x.limit+x.items.length)} из ${x.total}</small><nav aria-label="Страницы ключей"><button class="fo-button fo-icon-button" data-admin-list-page="${x.page-1}" ${x.page<=1?'disabled':''} aria-label="Предыдущая страница">${actionIcon('chevron-left')}</button><span>${x.page} / ${Math.max(1,Math.ceil(x.total/x.limit))}</span><button class="fo-button fo-icon-button" data-admin-list-page="${x.page+1}" ${x.page*x.limit>=x.total?'disabled':''} aria-label="Следующая страница">${actionIcon('chevron-right')}</button></nav><label class="fo-field">На странице<select class="fo-select" data-admin-list-limit aria-label="Записей на странице">${[10,25,50,100].map(n=>`<option ${Number(f.limit)===n?'selected':''}>${n}</option>`).join('')}</select></label></footer>`:''}</section>`;
 }

