function viewContent(d){if(deviceViews.includes(state.view))return deviceScreen();if(state.view==='subscriptions')return subscriptionShopPage();if(state.view==='gift-claim')return giftInvitationPage();if(state.view==='admin-catalog')return catalogPage();if(state.view==='admin-servers')return adminServersPage();if(state.view==='admin-payments')return paymentsPage();if(state.view==='admin-posts')return postsPage(true);if(state.view==='posts')return postsPage();if(state.view==='admin-reports')return reportsPage();if(state.view==='admin-dashboard')return adminProfilePage(d);if(state.view==='admin-clients')return adminClientsPage();if(state.view==='admin-customer')return adminCustomerPage();if(state.view==='admin-search')return adminGlobalPage();if(state.view==='admin-key')return adminKeyPage();if(state.view==='admin-keys'){state.extra.infrastructureTab='subscriptions';return adminServersPage();}if(state.view==='admin-proxy-server')return adminProxyServerPage();if(state.view==='admin-proxy'){state.extra.infrastructureTab='proxy';return adminServersPage();}if(state.view==='home'||state.view==='profile')return profilePage(d);if(state.view==='keys')return keysPage(d);if(state.view==='purchase')return purchasePage();if(state.view==='plans')return plansPage(d);if(state.view==='support')return supportPage(d);if(state.view==='balance')return balancePage();if(state.view==='referrals')return referralPage();if(state.view==='proxy')return proxyPage();if(state.view==='faq'||state.view==='instructions')return infoPage(state.view);if(state.view==='status')return placeholder('Статус сервисов','Публичный мониторинг ещё не подключён.');return placeholder('Раздел','Содержимое раздела готовится.')}
