function supportMessagePayload(ticketId,text,attachments){const f=app.querySelector('[data-support-message]');if(f&&!f.dataset.requestId)f.dataset.requestId=crypto.randomUUID();return {ticket_id:ticketId==='new'?null:ticketId,text,attachments,quick_reply_id:state.extra.supportSelectedQuick||null,client_mode:!state.data?.profile.is_admin,request_id:f?.dataset.requestId||crypto.randomUUID(),response_status:state.data?.profile.is_admin?'waiting_client':'waiting_client'}}
async function filePayload(file){if(file.size>20*1024*1024)throw new Error('Файл больше 20 МБ');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('Не удалось прочитать файл'));reader.onload=()=>resolve({name:file.name,mime_type:file.type,data:String(reader.result).split(',')[1]});reader.readAsDataURL(file)})}
async function filesPayload(input){const files=[...(input?.files||[])];if(files.length>6)throw new Error('Можно приложить до 6 файлов');return Promise.all(files.map(filePayload))}
/* Explicit, trusted-template component opt-in. No observers or lifecycle changes. */
function foTemplate(markup, components){
  const template=document.createElement('template');template.innerHTML=markup;
  for(const [selector,classes] of Object.entries(components))template.content.querySelectorAll(selector).forEach(node=>node.classList.add(...classes.split(' ')));
  return template.innerHTML;
}
/* B03 explicit opt-in; actions, field names and owner state stay in renderers. */
function foDialogMarkup(markup,{dirty=false,focus=''}={}){
  const template=document.createElement('template');template.innerHTML=markup;
  const root=template.content.querySelector('.modal-backdrop');if(!root)return markup;
  const panel=root.firstElementChild;if(!panel)return markup;
  root.classList.add('fo-overlay','fo-scope');root.dataset.foOverlay='dialog';
  if(dirty)root.dataset.foDirty='';if(focus)root.dataset.foFocus=focus;
  panel.classList.add('fo-dialog','fo-scope');panel.classList.remove('fo-card');panel.dataset.foPanel='';
  let header=panel.querySelector(':scope>header');
  if(!header){header=document.createElement('header');panel.prepend(header);const title=panel.querySelector(':scope>h2');if(title)header.append(title);const close=panel.querySelector(':scope>button[aria-label="Закрыть"]');if(close)header.append(close);}
  header.classList.add('fo-dialog-header');
  const title=header.querySelector('h2');if(title){title.id ||= 'fo-dialog-title';if(!panel.hasAttribute('aria-label'))panel.setAttribute('aria-labelledby',title.id);}
  panel.querySelectorAll('footer,.checkout-confirm-actions').forEach(n=>n.classList.add('fo-dialog-actions'));
  return template.innerHTML;
}
