let themeTransitionBusy=false;
async function toggleThemeAnimated(button){
  if(themeTransitionBusy)return;
  const root=document.documentElement,next=state.theme==='dark'?'light':'dark';
  let applied=false;
  const apply=()=>{if(applied)return;applied=true;state.theme=next;try{localStorage.setItem('freeman-theme',next)}catch{}root.dataset.theme=next;render();app.querySelector('[data-theme-toggle]')?.focus({preventScroll:true})};
  if(typeof document.startViewTransition!=='function'||typeof root.animate!=='function'||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches){apply();return}
  const width=window.innerWidth,height=window.innerHeight,rect=button.getBoundingClientRect();
  if(!width||!height){apply();return}
  const x=Math.max(0,Math.min(width,rect.left+rect.width/2)),y=Math.max(0,Math.min(height,rect.top+rect.height/2));
  const radius=Math.hypot(Math.max(x,width-x),Math.max(y,height-y))+2;
  const point=`${x/width*100}% ${y/height*100}%`,start=`circle(0% at ${point})`,end=`circle(${radius/(Math.hypot(width,height)/Math.SQRT2)*100}% at ${point})`;
  themeTransitionBusy=true;root.dataset.themeReveal='active';root.style.setProperty('--theme-reveal-from',start);root.style.setProperty('--theme-reveal-duration','400ms');
  let transition,animation;
  try{
    transition=document.startViewTransition(apply);
    await transition.ready;
    animation=root.animate({clipPath:[start,end]},{duration:400,easing:'ease-in-out',fill:'forwards',pseudoElement:'::view-transition-new(root)'});
    await animation.finished;
    await transition.finished;
  }catch{transition?.skipTransition?.();apply()}
  finally{animation?.cancel();delete root.dataset.themeReveal;root.style.removeProperty('--theme-reveal-from');root.style.removeProperty('--theme-reveal-duration');themeTransitionBusy=false}
}

