async function openSupportKeyDestination(){
  const query=new URL(location.href).searchParams;
  const id=Number(query.get('managed_key'));
  if(!Number.isSafeInteger(id)||id<1||!state.data.keys.some(key=>key.id===id))return false;
  state.expanded=id;
  await loadView('keys');
  if(state.view!=='keys')return true;
  document.querySelector('#key-name-'+id)?.scrollIntoView({block:'nearest'});
  if(query.get('key_action')==='antig'){
    const action=document.querySelector('[data-key-antig="'+id+'"]');
    if(action)action.click();
    else say('Антиглушилка для этой подписки сейчас недоступна.');
  }
  return true;
}

