function reportIcon(){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="M4 4v16h16M8 15v-4m5 4V6m5 9V9" stroke-linecap="round" stroke-linejoin="round"/></svg>'}
function reportsQuery(){const x=state.extra;return new URLSearchParams({period:x.reportPeriod||'month',start:x.reportStart||'',end:x.reportEnd||'',kind:x.reportKind||'all',page:x.reportPage||1,limit:x.reportLimit||10,...Object.fromEntries(Object.entries(x.reportFilters||{}).map(([k,v])=>[k,k==='months'&&v==='all'?-1:k==='devices'&&v==='all'?0:v]))})}
let reportSequence=0;
let reportRequest=null;
const reportCache=new Map();
async function loadReports(force=false){const key=reportsQuery().toString(),cached=reportCache.get(CabinetReads.scope()+':'+key);reportRequest?.abort();const seq=++reportSequence;if(!force&&cached&&Date.now()-cached.at<20000){state.extra.report=cached.data;state.extra.reportLoading=false;state.extra.reportError='';render();return}reportRequest=new AbortController();state.extra.reportLoading=true;state.extra.reportError='';render();try{const response=await fetch('/api/web/admin/reports?'+key,{cache:force?'reload':'no-store',signal:reportRequest.signal});if(!response.ok){const e=await response.json();throw Error(e.detail||'Не удалось загрузить отчёт')}const result=await response.json();if(seq===reportSequence){state.extra.report=result;reportCache.set(CabinetReads.scope()+':'+key,{at:Date.now(),data:result});if(reportCache.size>12)reportCache.delete(reportCache.keys().next().value)}}catch(e){if(seq===reportSequence&&e.name!=='AbortError')state.extra.reportError=e.message}finally{if(seq===reportSequence){state.extra.reportLoading=false;if(state.view==='admin-reports')render()}}}
function reportDay(value){return new Intl.DateTimeFormat('ru-RU',{weekday:'long',timeZone:'Europe/Moscow'}).format(new Date(value+'T12:00:00+03:00'))}
function reportDate(value){return new Intl.DateTimeFormat('ru-RU',{timeZone:'Europe/Moscow'}).format(new Date(value))}
function reportTime(value){return new Intl.DateTimeFormat('ru-RU',{hour:'2-digit',minute:'2-digit',second:'2-digit',timeZone:'Europe/Moscow'}).format(new Date(value))}
function analyticsIcon(name){const paths={calendar:'M5 5h14v15H5zM8 3v4M16 3v4M5 10h14',users:'M8 12a4 4 0 1 0 0-8 4 4 0 0 0 0 8M2 21v-3a6 6 0 0 1 12 0v3M17 5a4 4 0 0 1 0 7M18 15a5 5 0 0 1 4 5',wallet:'M4 5h15v15H4zM4 8h15M19 12h-5v4h5M16 14h1',key:'M8 14a5 5 0 1 0 0-10 5 5 0 0 0 0 10M12 12l9 9M17 17l3-3M19 19l3-3','shopping-cart':'M2 3h3l3 13h11l3-10H6M9 21h1M18 21h1','trending-up':'M3 17l6-6 4 4 8-10M15 5h6v6','refresh-cw':'M20 8a8 8 0 1 0 0 9M20 3v5h-5'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths.wallet}"/></svg>`}
function analyticsEmpty(text='Нет данных за выбранный период'){return `<p class="analytics-empty">${esc(text)}</p>`}
function analyticsGrowth(v){return v==null?'<small class="analytics-change">Нет базы сравнения</small>':`<small class="analytics-change ${v>0?'up':v<0?'down':''}">${v>0?'↑ +':v<0?'↓ ':''}${new Intl.NumberFormat('ru-RU').format(v)}% <span>к предыдущему периоду</span></small>`}
function analyticsKpi(label,value,key,d,icon='chart',secondary=false,action=''){return `<${action?'button':'article'} class="analytics-kpi ${secondary?'secondary':''}" ${action?`data-report-keys="${action}"`:''}><span class="analytics-icon ${key}">${analyticsIcon(icon)}</span><div><span>${label}</span><strong class="${value==='Недостаточно данных'?'unavailable':''}">${value}</strong>${secondary?'':key==='profit'?'<small class="analytics-change">Нужен полный учёт затрат</small>':analyticsGrowth(d.stats[key+'_growth'])}</div></${action?'button':'article'}>`}
function analyticsChart(rows,mode='sales'){rows=rows.filter(r=>!r.future);if(!rows.some(r=>r.sales||r.new_customers||r.returning))return analyticsEmpty('Нет продаж за выбранный период');const w=680,h=210,left=40,right=48,top=14,bottom=30,plot=w-left-right,ph=h-top-bottom;const stacked=mode==='customers'||mode==='renewals';const av=rows.map(r=>mode==='customers'?(r.new_customers||0)+(r.returning||0):r.sales),max=Math.max(4,Math.ceil(Math.max(1,...av)/4)*4),money=Math.max(1,...rows.map(r=>r.revenue||0)),step=plot/rows.length;let paths=[],rects=[];rows.forEach((r,i)=>{const x=left+(i+.5)*step,base=mode==='customers'?r.new_customers||0:mode==='renewals'?r.new_sales||0:r.sales,other=mode==='customers'?r.returning||0:mode==='renewals'?r.renewals||0:0,bar=Math.max(2,Math.min(22,step*.64)),bh=base/max*ph,oh=other/max*ph;const tip=mode==='customers'?`${reportDate(r.date+'T12:00:00+03:00')} · Новые: ${base}, вернувшиеся: ${other}`:`${reportDate(r.date+'T12:00:00+03:00')} · Продажи: ${r.sales}, выручка: ${rub(r.revenue)}, продления: ${r.renewals||0}`;rects.push(`<g tabindex="0" data-report-tooltip="${esc(tip)}" aria-label="${esc(tip)}"><title>${esc(tip)}</title><rect x="${x-bar/2}" y="${h-bottom-bh}" width="${bar}" height="${bh}" rx="2" fill="${stacked?'#0A84FF':'#B8D9FF'}"/>${stacked?`<rect x="${x-bar/2}" y="${h-bottom-bh-oh}" width="${bar}" height="${oh}" rx="2" fill="#B8D9FF"/>`:''}<rect x="${x-step/2}" y="${top}" width="${step}" height="${ph}" fill="transparent"/></g>`);paths.push(`${x},${h-bottom-(r.revenue||0)/money*ph}`)});const labels=[0,Math.floor(rows.length/3),Math.floor(rows.length*2/3),rows.length-1].filter((v,i,a)=>a.indexOf(v)===i);return `<div class="analytics-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${mode==='customers'?'Новые и вернувшиеся клиенты':mode==='renewals'?'Новые продажи и продления':'Продажи и выручка'}">${[0,1,2,3,4].map(i=>{const y=top+ph*i/4;return `<path d="M${left} ${y}H${w-right}" stroke="var(--analytics-line)"/><text x="${left-8}" y="${y+4}" text-anchor="end">${Math.round(max*(1-i/4))}</text>${stacked?'':`<text x="${w-right+8}" y="${y+4}">${new Intl.NumberFormat('ru-RU',{notation:'compact'}).format(money*(1-i/4)/100)}</text>`}`}).join('')}${rects.join('')}${stacked?'':`<polyline points="${paths.join(' ')}" fill="none" stroke="#34C759" stroke-width="2.4" pointer-events="none"/>${paths.length===1?`<circle cx="${paths[0].split(',')[0]}" cy="${paths[0].split(',')[1]}" r="3" fill="#34C759"/>`:''}`}${labels.map(i=>`<text x="${left+(i+.5)*step}" y="${h-8}" text-anchor="middle">${esc(new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'short'}).format(new Date(rows[i].date+'T12:00:00+03:00')))}</text>`).join('')}</svg></div>`}
function analyticsDonut(values,labels){const entries=Object.entries(values).filter(([,v])=>v>0),total=entries.reduce((a,[,v])=>a+v,0),colors=entries.map(([k])=>({active:'#34C759',expiring:'#FF9F0A',expired:'#FF453A',blocked:'#8A94A6',stopped:'#B8C3D5'}[k]||'#B8C3D5'));if(!total)return analyticsEmpty('Нет подписок');let offset=0;const stops=entries.map(([k,v],i)=>{const from=offset;offset+=v/total*100;return `${colors[i]} ${from}% ${offset}%`});return `<div class="analytics-distribution"><div class="analytics-donut" style="background:conic-gradient(${stops.join(',')})" role="img" aria-label="${esc(entries.map(([k,v])=>(labels[k]||k)+': '+v).join(', '))}"><span><strong>${total}</strong><small>всего</small></span></div><dl>${entries.map(([k,v],i)=>`<div><dt><i style="background:${colors[i]}"></i>${esc(labels[k]||k)}</dt><dd>${v}<small>${Math.round(v/total*100)}%</small></dd></div>`).join('')}</dl></div>`}
function analyticsRanks(rows,sort='sales',field='name'){
 const sorted=[...rows].sort((a,b)=>b[sort]-a[sort]),total=rows.reduce((a,r)=>a+r.sales,0);
 return sorted.length?`<ol class="analytics-ranks">${sorted.map((r,i)=>`<li><span>${i+1}</span><button class="fo-button fo-button--plain" data-report-plan="${r.kind||'vpn'}" data-months="${r.months??'all'}" data-devices="${r.devices||0}" title="Показать все продажи по этому сроку и лимиту"><strong>${esc(r[field])}</strong>${r.min_price!=null?`<small>${r.tariff_id?'Тариф #'+esc(r.tariff_id):'Без ID тарифа · историческая продажа'} · ${rub(r.min_price)}${Number(r.max_price)!==Number(r.min_price)?' — '+rub(r.max_price):''}</small>`:''}</button><b>${sort==='revenue'?rub(r.revenue):r.sales}</b><div class="analytics-track"><i style="width:${r.sales/Math.max(1,total)*100}%"></i></div><small>${Math.round(r.sales/Math.max(1,total)*100)}%</small></li>`).join('')}</ol>`:analyticsEmpty();
}
function analyticsFacts(rows){return `<dl class="analytics-facts">${rows.map(([a,b])=>`<div><dt>${a}</dt><dd>${b}</dd></div>`).join('')}</dl>`}
function analyticsGroup(tariffs,key){const map=new Map();for(const t of tariffs.filter(t=>t.kind==='vpn')){const val=t[key];if(val==null)continue;const label=key==='months'?(val===0?'24 часа':val+' мес.'):val+' устр.';const r=map.get(val)||{name:label,sales:0,revenue:0,kind:'vpn',[key]:val};r.sales+=t.sales;r.revenue+=t.revenue;map.set(val,r)}return [...map.values()]}
