function analyticsTimeline(d){
 const table=state.extra.reportDisplay==='table',rows=d.series.filter(row=>!row.future);
 const totals=rows.reduce((a,r)=>({sales:a.sales+(r.sales||0),revenue:a.revenue+(r.revenue||0),renewals:a.renewals+(r.renewals||0)}),{sales:0,revenue:0,renewals:0});
 return `<div class="analytics-view-switch" aria-label="Вид отчёта"><button data-report-display="chart" aria-pressed="${!table}">График</button><button data-report-display="table" aria-pressed="${table}">Таблица</button></div>${table?`<div class="analytics-summary-table"><table><thead><tr><th>${d.bucket==='month'?'Месяц':d.bucket==='week'?'Неделя с':'Дата'}</th><th>Продажи</th><th>Выручка</th><th>Продления</th><th>Средний чек</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(reportDate(r.date+'T12:00:00+03:00'))}</td><td>${r.sales||0}</td><td>${rub(r.revenue||0)}</td><td>${r.renewals||0}</td><td>${rub(r.sales?r.revenue/r.sales:0)}</td></tr>`).join('')||'<tr><td colspan="5">Нет данных за период</td></tr>'}</tbody><tfoot><tr><th>Итого</th><td>${totals.sales}</td><td>${rub(totals.revenue)}</td><td>${totals.renewals}</td><td>${rub(totals.sales?totals.revenue/totals.sales:0)}</td></tr></tfoot></table></div>`:analyticsChart(d.series)}`;
}
async function downloadReportCSV(mode){
 if(reportExportBusy||!state.extra.report||state.extra.reportLoading||state.extra.reportError)return;
 const report=state.extra.report,query=reportsQuery(),filename=`freeman-${mode==='daily'?'summary':'sales'}-${report.start}-${report.end}.csv`;
 reportExportBusy=true;const buttons=[...document.querySelectorAll('[data-report-export]')];buttons.forEach(button=>button.disabled=true);
 try{
  let blob;
  if(mode==='daily'){
   const cell=value=>{let text=String(value??'');if(/^[=+@]/.test(text))text="'"+text;return '"'+text.replace(/"/g,'""')+'"'};
   const rows=[['Дата МСК','Группировка','Продажи','Выручка ₽','Новые продажи','Продления','Средний чек ₽'],...report.series.filter(r=>!r.future).map(r=>[r.date,report.bucket==='month'?'Месяц':report.bucket==='week'?'Неделя':'День',r.sales||0,((r.revenue||0)/100).toFixed(2),r.new_sales||0,r.renewals||0,(r.sales?r.revenue/r.sales/100:0).toFixed(2)])];
   blob=new Blob(['\ufeff'+rows.map(row=>row.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});
  }else{
   query.set('export','csv');const response=await fetch('/api/web/admin/reports?'+query,{cache:'no-store'});
   if(!response.ok){let message='Не удалось выгрузить CSV';try{message=(await response.json()).detail||message}catch{}throw Error(message)}
   if(!response.headers.get('content-type')?.includes('text/csv'))throw Error('Сервер вернул некорректный файл. Повторите выгрузку.');
   blob=await response.blob();
  }
  const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);document.querySelector('.analytics-export')?.removeAttribute('open');say('CSV готов: '+(mode==='daily'?'сводка по датам':'все продажи с текущими фильтрами'));
 }catch(error){say(error.message)}finally{reportExportBusy=false;document.querySelectorAll('[data-report-export]').forEach(button=>button.disabled=!!state.extra.reportLoading)}
}
