function flexibleRenewModal(id,x=state.extra.renewDetails){const detail=x?.key?.id===id?x:null;return `<div class="modal-backdrop"><form class="form-modal key-renew-dialog" data-admin-key-form data-key-id="${id}" data-operation="extend"><header class="key-dialog-heading"><span class="key-dialog-icon">${actionIcon('calendar')}</span><div><h2>Продлить подписку</h2><p>Ключ #${id}${detail?.key?' · '+esc(keysTitle(detail.key)):''}</p></div><button type="button" data-close-modal aria-label="Закрыть">${actionIcon('close')}</button></header>${detail?.key?`<p class="key-renew-current">Текущий срок: ${new Date(detail.key.expires_at).toLocaleString('ru-RU')}</p>`:''}<section><h3>Срок продления</h3><div class="key-renew-fields"><label data-renew-duration>Количество<input name="value" type="number" min="1" max="3650" value="30" required></label><label>Единица срока<select name="unit"><option value="hours">Часы</option><option value="days" selected>Дни</option><option value="weeks">Недели</option><option value="months">Месяцы · 30 дней</option><option value="date">До даты и времени</option></select></label></div><label data-renew-date hidden>Новая дата окончания<input name="expires_at" type="datetime-local"></label><div class="key-renew-presets">${[[1,'1 час'],[24,'24 часа'],[168,'7 дней'],[720,'30 дней'],[2160,'90 дней']].map(([hours,label])=>`<button type="button" data-renew-hours="${hours}">${label}</button>`).join('')}</div>${detail?.renewal_options?.length?`<label>Шаблон тарифа<select data-renew-tariff><option value="">Свои параметры</option>${detail.renewal_options.map(t=>`<option value="${t.id}" data-days="${t.days}" data-price="${t.price}">${t.months} мес. · ${t.device_limit} устр. · ${rub(t.price)}</option>`).join('')}</select></label>`:''}<p class="key-renew-explanation">Срок добавляется к действующей подписке. Для истёкшей — отсчитывается от текущего времени.</p></section><section><h3>Оплата</h3><label>Способ<select name="payment_mode"><option value="free">Без оплаты · административное продление</option><option value="balance">Списать с баланса клиента</option><option value="manual">Оплата уже получена вручную</option></select></label><label data-renew-amount hidden>Сумма, ₽<input name="amount" type="number" min="0.01" step="0.01" value="0" disabled></label><label class="key-renew-paid-confirm" data-renew-paid-confirm hidden><input name="payment_confirmed" type="checkbox">Подтверждаю, что оплата действительно получена</label><p class="key-renew-payment-note" data-renew-payment-note>Оплата и продажа не создаются. Изменение сохраняется в журнале администратора.</p></section><div class="key-renew-preview" data-renew-preview></div><p class="login-form-error" hidden role="alert"></p><footer><button type="button" data-close-modal>Отмена</button><button class="checkout-button" type="submit">Продлить</button></footer></form></div>`}
function renewPreview(){const f=document.querySelector('.key-renew-dialog');if(!f)return;const unit=f.elements.unit.value,payment=f.elements.payment_mode.value,isDate=unit==='date',paid=payment!=='free';f.querySelector('[data-renew-duration]').hidden=isDate;f.elements.value.required=!isDate;f.elements.value.disabled=isDate;f.querySelector('[data-renew-date]').hidden=!isDate;f.elements.expires_at.required=isDate;f.elements.value.max=({hours:87600,days:3650,weeks:521,months:121})[unit]||3650;f.querySelector('[data-renew-amount]').hidden=!paid;f.elements.amount.disabled=!paid;f.elements.amount.required=paid;f.querySelector('[data-renew-paid-confirm]').hidden=payment!=='manual';f.elements.payment_confirmed.required=payment==='manual';f.querySelector('[data-renew-payment-note]').textContent=payment==='free'?'Оплата и продажа не создаются. Изменение сохраняется в журнале администратора.':payment==='balance'?'Сумма будет списана с баланса клиента. При нехватке средств срок не изменится.':'Это учёт уже полученной оплаты. Банковская операция не выполняется; запись войдёт в отчёт продаж.';const k=state.extra.renewDetails?.key?.id===Number(f.dataset.keyId)?state.extra.renewDetails.key:null,base=Math.max(Date.now(),k?new Date(k.expires_at).getTime():0),hours=Number(f.elements.value.value)*({hours:1,days:24,weeks:168,months:720})[unit],end=isDate&&f.elements.expires_at.value?new Date(f.elements.expires_at.value):new Date(base+hours*3600000);f.querySelector('[data-renew-preview]').textContent=(Number.isNaN(end.getTime())?'Укажите новую дату окончания':'Новый срок: '+end.toLocaleString('ru-RU'))+' · '+(paid?rub(Math.round(Number(f.elements.amount.value||0)*100)):'Без оплаты')}
document.addEventListener('input',e=>{if(e.target.closest('.key-renew-dialog'))renewPreview()});document.addEventListener('change',e=>{const f=e.target.closest('.key-renew-dialog');if(!f)return;if(e.target.matches('[data-renew-tariff]')){const option=e.target.selectedOptions[0];if(option.dataset.days){f.elements.unit.value='days';f.elements.value.value=option.dataset.days;f.elements.amount.value=Number(option.dataset.price)/100}}renewPreview()});document.addEventListener('click',e=>{const p=e.target.closest('[data-renew-hours]');if(!p)return;const f=p.closest('form');f.elements.unit.value='hours';f.elements.value.value=p.dataset.renewHours;renewPreview()});
