async function manualRequest(url,payload){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),payload?60000:15000);try{const r=await fetch(url,{...(payload?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)}:{}),signal:controller.signal});let x;try{x=await r.json()}catch{throw Error('Нет подтверждённого ответа. Проверьте тот же запрос ещё раз.')}if(!r.ok){const error=Error(typeof x.detail==='string'?x.detail:'Проверьте параметры выдачи');error.status=r.status;throw error}return x}catch(error){if(error.name==='AbortError'||error instanceof TypeError)throw Error('Связь прервалась. Проверьте тот же запрос; новую выдачу создавать не нужно.');throw error}finally{clearTimeout(timer)}}
