async function manualQuoteRefresh(){const f=document.querySelector('[data-manual-sale]');if(!f||ManualSales.payload)return;const seq=++ManualSales.epoch,category=f.elements.issuance_kind.value,commercial=category==='manual_sale',button=f.querySelector('[type=submit]');ManualSales.quote=null;button.disabled=true;f.querySelector('[data-manual-tariff]').hidden=!commercial;f.querySelector('[data-manual-custom]').hidden=commercial;f.querySelector('[data-manual-received]').hidden=!commercial;const info=f.querySelector('[data-manual-quote]');if(!commercial){f.elements.payment_received.checked=false;info.textContent='Без оплаты · '+(category==='test'?'тест':'подарок');button.disabled=!ManualSales.options.available&&!ManualSales.context.key_id;return}
 info.textContent='Рассчитываем стоимость…';try{const x=await manualRequest('/api/web/admin/manual-sales/quote',{tariff_id:Number(f.elements.tariff_id.value),key_id:ManualSales.context.key_id||null,user_id:ManualSales.context.user_id||null,identity:f.elements.identity?.value.trim()||'',external_phone:f.elements.external_phone?.value.trim()||''});if(seq!==ManualSales.epoch||!f.isConnected)return;ManualSales.quote=x;info.textContent='Стоимость продажи: '+rub(x.amount)+' · '+x.months+' календарных мес. · '+x.devices+' устр.';button.disabled=!ManualSales.options.available&&!ManualSales.context.key_id}catch(error){if(seq===ManualSales.epoch&&f.isConnected)info.textContent=error.message}}
async function manualSaleSubmit(f){const button=f.querySelector('[type=submit]'),error=f.querySelector('.login-form-error');button.disabled=true;error.hidden=true;let payload=ManualSales.payload;try{if(!payload){const category=f.elements.issuance_kind.value,q=ManualSales.quote,renewal=ManualSales.context.key_id;if(category==='manual_sale'&&!q)throw Error('Сначала получите актуальный расчёт цены.');payload={request_id:crypto.randomUUID(),issuance_kind:category,tariff_id:category==='manual_sale'?q.tariff_id:null,expected_amount:category==='manual_sale'?q.amount:null};const days=category==='manual_sale'?q.days:Number(f.elements.days.value);if(renewal)Object.assign(payload,{key_id:renewal,action:'extend',value:String(days),unit:'days',confirmed:true,payment_confirmed:f.elements.payment_received.checked});else Object.assign(payload,{identity:f.elements.identity.value.trim(),external_phone:f.elements.external_phone.value.trim(),user_id:ManualSales.context.user_id||null,days,device_limit:category==='manual_sale'?q.devices:Number(f.elements.device_limit.value),name:f.elements.name.value.trim(),payment_received:f.elements.payment_received.checked});
 if(!renewal&&!payload.identity&&!payload.external_phone&&!payload.user_id)throw Error('Укажите Freeman ID или телефон клиента.');
 // Do not dispatch without durable browser recovery. Contains only issuance
 // parameters, never connection URLs, provider tokens or account credentials.
 localStorage.setItem(manualStorage(),JSON.stringify(payload));ManualSales.payload=payload;}
 const result=await manualRequest(payload.key_id?'/api/web/admin/keys/'+payload.key_id+'/action':'/api/web/admin/keys/grant',payload);localStorage.removeItem(manualStorage());ManualSales.payload=null;state.modal=null;render();if(payload.key_id){await loadAdminKeys();if(state.view==='admin-key')await openAdminKey(payload.key_id)}else await openAdminCustomer(result.user_id);say('Подписка подтверждена · '+(result.issuance_kind==='manual_sale'?(result.payment_received?'оплачена':'оплата ожидается'):'без оплаты'))
 }catch(problem){error.textContent=problem.message;error.hidden=false;if(problem.status===422||problem.status===409){try{await manualRequest('/api/web/admin/manual-sales/operations/'+payload.request_id)}catch(check){if(check.status===404){localStorage.removeItem(manualStorage());ManualSales.payload=null;}}}if(ManualSales.payload){f.querySelector('fieldset').disabled=true;button.textContent='Проверить / продолжить'}}finally{if(button.isConnected)button.disabled=false}}

app.addEventListener('change',e=>{if(e.target.closest('[data-manual-sale]')&&['tariff_id','issuance_kind'].includes(e.target.name))manualQuoteRefresh()});

app.addEventListener('click',async e=>{if(!e.target.closest('[data-manual-advanced]'))return;try{const id=ManualSales.context.key_id;const x=await manualRequest('/api/web/admin/keys/'+id);state.extra.renewDetails=x;state.modal=flexibleRenewModal(id,x);render();renewPreview()}catch(error){say(error.message)}});

